    # 3.2 设计范围及要求
    {"id": "sp-063", "clause": "第五章3.2设计范围及要求", "page": "n/a-无分页",
     "requirement": "设计范围与整体设计协调服务", "required_value": "含升压站初步设计、施工图设计、竣工图编制、设备技术规范编制等阶段；文件编制深度满足现行标准规程规范；负责整体设计协调服务（含现场服务）、审核配合、设计交底与审查", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "设计范围包括升压站初步设计、施工图设计、竣工图编制、各类设备技术规范编制等阶段。各设计阶段文件编制深度应分别满足国家和行业现行的标准、规程、规范及相关规定的要求。负责项目整体设计协调和服务（含现场服务），配合所有设计文件和图纸的审核通过和各项审查、验收、备案、文件归档，负责各类设计交底、设计审查工作。（P3409）"},
    {"id": "sp-064", "clause": "第五章3.2设计范围及要求", "page": "n/a-无分页",
     "requirement": "施工图纸审核与提供时限", "required_value": "经发包人和监理人审核同意，施工前10天提供", "unit": "天",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "用于工程施工的安装图、布置图、开挖图、配筋图、细部设计图、装修图等施工图纸，应经发包人和监理人审核同意，在施工前10天提供给承包人。（P3410）"},
