    {"id": "sp-148", "clause": "第五章8.2.3工程竣工验收承包商应提供的资料", "page": "n/a-无分页",
     "requirement": "竣工验收备查文件资料15项（P4949–P4963）：施工设计图纸文件（含设计更改联系单）/施工记录及有关试验检测报告/监理质监检查记录和签证文件/各单位工程完工与单机启动调试验收记录签证/历次验收问题整改消缺记录报告/各阶段设计与审批文件/设备产品技术说明书使用手册合格证件/施工及设备订货合同技术要求文件/传真与设计施工协调会议纪要/工程建设大事记/设备备品配件及专用工器具清单/性能指标参数/消防防雷监测安全职业卫生水保环保验收证书/工程竣工决算/工程竣工报告", "required_value": "竣工验收备查文件资料完整提供", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "备查文件、资料：（P4948）"},
    # 8.2.4 验收程序（P4964 标题）
