    # 8.4 对项目发包人人员的操作培训（P5009 标题；填空残片 _/__ 照录）
    {"id": "sp-177", "clause": "第五章8.4对项目发包人人员的操作培训", "page": "n/a-无分页",
     "requirement": "培训计划递交与确认时限（含发包人填空项）", "required_value": "签订合同后约定周数内递交详细培训计划；业主约定周数内确定；提前约定个月书面提供；承包商安排应满足业主计划要求；培训内容与工程进度相一致", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（一）为使合同设备能正常安装、调试、运行、维护及检修，承包商将提供相应的技术培训。培训内容应与工程进度相一致，承包商在签订合同后_  _周内将详细的培训计划递交业主审查，业主在_ __周内确定培训计划，提前__ _个月书面形式提供给承包商，承包商的安排应满足业主的计划要求。（P5010）"},
    {"id": "sp-178", "clause": "第五章8.4对项目发包人人员的操作培训", "page": "n/a-无分页",
     "requirement": "工厂培训时间与费用归属（培训费包含在设备费内）", "required_value": "合同生效后约定周数内工厂培训，培训时间约定天数；培训费包含在设备费内", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（二）培训内容和地点（培训费包含在设备费内）……A、培训时间：合同生效后的第__周内，培训时间约为__天。（P5011；P5013）"},
    {"id": "sp-179", "clause": "第五章8.4对项目发包人人员的操作培训", "page": "n/a-无分页",
     "requirement": "工厂培训内容-风电机组知识培训", "required_value": "风电机组知识培训", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "a、风电机组知识培训（P5015）"},
    {"id": "sp-180", "clause": "第五章8.4对项目发包人人员的操作培训", "page": "n/a-无分页",
     "requirement": "工厂培训内容-风机吊装及维护现场培训", "required_value": "风机吊装及维护现场培训", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "b、风机吊装及维护现场培训（P5016）"},
    {"id": "sp-181", "clause": "第五章8.4对项目发包人人员的操作培训", "page": "n/a-无分页",
     "requirement": "工厂培训人员及费用", "required_value": "发包人派遣人员不多于约定人数，差旅费发包人自行承担，其他费用承包商承担", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "C、人员及费用：发包人派遣的人员不多于__人，派遣人员的差旅费由发包人自行承担。其他费用由承包商承担。（P5017）"},
