    # 8.8 保修工作范围（P5086 标题；填空残片 __24_ 照录）
    {"id": "sp-212", "clause": "第五章8.8保修工作范围", "page": "n/a-无分页",
     "requirement": "缺陷责任期内缺陷处理与费用扣罚", "required_value": "缺陷责任期（颁发接收证书后约定月数）内完成承包范围缺陷处理；处理不满足业主生产管理要求时业主有权委托他方处理并扣除已支付费用的100%（按电力取费标准）；停机处理缺陷不超过机组运行等效可用系数要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本项目承包商的缺陷责任期为业主颁发接收证书后__24_个月。在缺陷责任期内完成该过程承包范围承包商责任的任何缺陷处理，若承包商处理缺陷不能满足业主生产管理的要求，则业主有权直接委托其它单位处理，并且扣除该缺陷处理、有关试验及承包商厂家配合业主已支付费用的100%，取费按照电力取费标准执行。缺陷责任期内发生停机处理的缺陷不能超过机组运行等效可用系数的要求。（P5087）"},
