    {"id": "sp-219", "clause": "第五章8.9.3符号、单位、格式和文件术语", "page": "n/a-无分页",
     "requirement": "标准符号单位格式术语按购发包人程序", "required_value": "流程图、逻辑模拟图、电气单线图和设备编码标识中的标准符号、单位、文件格式和术语按购发包人规定的有关程序执行", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "用于流程图、逻辑模拟图、电气单线图和设备编码标识中的标准符号、单位、文件格式和术语将按照购发包人规定的有关程序的规定要求。（P5101）"},
    {"id": "sp-220", "clause": "第五章8.9.3符号、单位、格式和文件术语", "page": "n/a-无分页",
     "requirement": "「批准」定义之承包人对图纸资料准确性全责（不因发包人批准减责）", "required_value": "承包人对所有提供图纸、资料以及有关说明书的准确性、设计完整性和设计深度负全责，不因发包人批准而减轻责任", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "·批准——指书面认可，包括发包人对先前口头同意事项的事后书面确认。……承包人应对所有提供图纸、资料以及有关说明书的准确性，设计的完整性和设计深度负全责，并不由于发包人的批准，而减轻其应承担的责任。（P5108）"},
    # 8.9.4 文件和图纸封面格式（P5115 标题；a–i 共 9 项并列按组一行）
    {"id": "sp-221", "clause": "第五章8.9.4文件和图纸封面格式", "page": "n/a-无分页",
     "requirement": "文件图纸封面内容9项（P5117–P5125）：a文件编码（按文件编码系统）/b文件标题（不建议用缩写）/c文件版本字母标识/d出版日期/e起草审核批准人名及签字/f文件修订简要说明/g承包人内部（参考）编码/h总页数/i系统设备和建筑物标识（如要求）", "required_value": "每一份文件或图纸的封面至少包括 a–i 全部内容", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "每一份文件或图纸的封面至少应包括以下内容：……a文件编码，根据文件编码系统……i系统、设备和建筑物的标识（如果要求）（P5116；P5117；P5125）"},
    {"id": "sp-222", "clause": "第五章8.9.4文件和图纸封面格式", "page": "n/a-无分页",
     "requirement": "封面其它要求按双方同意程序", "required_value": "文件和图纸封面的其它要求在工程中由购发包人出版并经双方同意的程序规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "文件和图纸封面的其它要求将在工程中由购发包人出版并经双方同意的程序规定。（P5126）"},
    # 8.9.5 电子文件要求（P5127 标题）
    {"id": "sp-223", "clause": "第五章8.9.5电子文件要求", "page": "n/a-无分页",
     "requirement": "电子文件版本格式", "required_value": "图纸文件为可编辑的AUTOCAD及PDF签字扫描版；文本文件为WORD/EXCEL格式", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电子文件的提交图纸文件的版本为可编辑的AUTOCAD及PDF签字扫描版，文本文件为WORD/EXCEL格式。（P5128）"},
    # 8.9.6 文件提交（P5129 标题）
    {"id": "sp-224", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "合同相关活动全部文件提供义务", "required_value": "按合同要求提供与合同相关活动的所有文件（含标准参考文件）；未列入技术资料清单但工程必需的文件资料一经发现及时免费提供", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应按合同要求向发包人提供与合同相关的活动的所有文件，包括标准参考文件。对于其它没有列入合同技术资料清单，确是工程所必需的文件和资料，一经发现，承包人也应及时免费提供。（P5130）"},
    {"id": "sp-225", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "文件版次标识与最终文件唯一版及变动赔偿", "required_value": "所有文件标识明确版次或最终版提交；最终文件只能有一版；承包人对“最终”文件变动造成发包人损失（设计施工返工、材料设备修改等）负责赔偿", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "设计中提供的所有文件应标识明确的版次或最终版提交。根据总的合同条件提交所有最终文件（最终文件只能有一版）。承包人对其提交的“最终”文件的变动造成发包人的损失包括设计和施工返工，材料、设备修改等负责赔偿。（P5131）"},
    {"id": "sp-226", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "文件图纸升版修改标记", "required_value": "提交的文件和图纸的改变（如升版）必须对修改之处作标记，便于发包人找到改变之处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人提交的文件和图纸的改变（如升版）必须对修改之处作标记，以便于发包人清楚地找到改变之处。（P5132）"},
    {"id": "sp-227", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "最终认可前禁止装运与施工", "required_value": "在相关图纸和设计文件最终认可之前，承包人不应开始设备的装运和现场的施工活动", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "在相关的图纸和设计文件最终认可之前，承包人不应开始设备的装运和现场的施工活动。（P5133）"},
    {"id": "sp-228", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "投标文件提交文件进度表与清单及交付进度", "required_value": "投标文件中提交提供文件的时间进度表和文件清单（合同谈判时由发包人确认）；设计文件交付进度满足基本设计、详细设计、安装、调试、竣工等阶段进度要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应在投标文件中提交提供文件的时间进度表和文件清单，在合同谈判时由发包人确认。承包人的设计文件交付进度应满足本工程基本设计、详细设计、安装阶段、调试阶段、竣工等发包人提出的工程进度的要求。（P5134）"},
    {"id": "sp-229", "clause": "第五章8.9.6文件提交", "page": "n/a-无分页",
     "requirement": "联络文件编号与文件流转程序", "required_value": "联络文件（传真、会议纪要、设计及设备变更联系单等）按发包人同意的方式编号，并执行发包人文件流转程序", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "项目执行过程中，承包人和发包人之间的联络文件如传真、会议纪要、设计及设备变更联系单等应以发包人同意的方式进行编号。并执行发包人的文件流转程序。（P5135）"},
