    {"id": "sp-258", "clause": "第五章1.1基本要求", "page": "n/a-无分页",
     "requirement": "投资控制目标与造价限额管理", "required_value": "严格控制设计变更、变更设计费用，及时严格按合同要求作好现场签证工作；加强施工承包合同结算管理，总投资控制在确定的工程造价限额以内，项目工程造价控制在执行概算内", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "投资控制目标：严格控制设计变更、变更设计费用,及时严格按合同要求作好现场签证工作。加强施工承包合同的结算管理，总投资控制在确定的工程造价限额以内。项目工程造价控制在执行概算内；项目工程造价管理水平保持在国内同类型机组、同类型地区的先进水平。（P3247）"},
    # 1.2 工作界区（P3249–P3292：EPC 边界与总包范围引言不抽，1.2.1 设计 9 行＋
    #     1.2.2 采购 6 行＋1.2.3 施工 7 行＋1.2.4 调试验收 2 行＋1.2.5 征租地 5 行＋
