    {"id": "sp-357", "clause": "第五章4.2.2设备安装", "page": "n/a-无分页",
     "requirement": "风电场内设备安装范围", "required_value": "钢塔筒、机舱、叶片、相关附件、塔筒门梯安装、塔筒内动力电缆（1140V）及桥架安装、变流器安装、箱式变压器安装，集电线路、送出线路架线等所有电气设备安装", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场内：钢塔筒、机舱、叶片、相关附件、塔筒门梯安装、塔筒内动力电缆（1140V）及桥架安装、变流器安装、箱式变压器安装，集电线路、送出线路架线等所有电气设备安装。（P3626）"},
    {"id": "sp-358", "clause": "第五章4.2.2设备安装", "page": "n/a-无分页",
     "requirement": "升压站内设备安装范围", "required_value": "主变，高低压配电装置，SVG、接地变，站用变、控制设备、测量、保护、通信、交直流控制电源设备及电、照明、消防、给排水设备、接地安装等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站内：主变，高低压配电装置，SVG、接地变，站用变、控制设备、测量、保护、通信、交直流控制电源设备及电、照明、消防、给排水设备、接地安装等。（P3627）"},
    {"id": "sp-359", "clause": "第五章4.2.2设备安装", "page": "n/a-无分页",
     "requirement": "设备材料采购与供应全流程责任", "required_value": "本工程所需的所有设备材料均由承包人负责采购、订货、驻厂验收、催货、提货、运输、保管等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程所需的所有设备材料均由承包人负责采购、订货、驻厂验收、催货、提货、运输、保管等。（P3628）"},
    {"id": "sp-360", "clause": "第五章4.2.2设备安装", "page": "n/a-无分页",
     "requirement": "设备设施标识标牌与安全警示划线", "required_value": "设备设施标识标牌、安全标识标志标牌制作与安装、安全警示标示线划线，符合国家安全设施配置标准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "设备设施标识标牌、安全标识标志标牌制作与安装、安全警示标示线划线，符合国安全设施配置标准。（P3629）"},
    {"id": "sp-361", "clause": "第五章4.2.2设备安装", "page": "n/a-无分页",
     "requirement": "设备吊装主吊载荷限制", "required_value": "80%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "设备吊装主吊载重不超过其额定载荷的80%。（P3630）"},
    # —— A2b：4.3.1 概述（P3633–P3642 10 行）＋4.3.2 风力发电机组（P3645、P3647–
    #     P3654、P3656–P3659、P3665、P3667、P3669、P3671、P3672、P3675–P3678
    #     共 22 行；P3644/P3646/P3655/P3660–P3664/P3666/P3668/P3670 引言·定义·
    #     公式·标题不抽；P3673 编号项「8）」误用 Heading 2 样式，照录登记）——
    {"id": "sp-362", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "装机规模与集电接入方式", "required_value": "单机容量6.25MW、总装机规模100MW；新建1座220kV开关站，采用35kV集电线路接入升压站", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "示例发包人示例市100MW风电场设计安装单机容量为 6.25MW 的风力发电机组，总装机规模为 100MW。风电场新建1座 220kV 开关站，采用35kV 集电线路接入升压站。（P3633）"},
    {"id": "sp-363", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "出口电压、箱变台数与接线方式", "required_value": "风电机组出口电压1140V；配套16台箱式变电站升压；风电机组与箱式变采用一机一变单元接线方式", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "本工程风电机组出口电压 1140 V，配套选用16台箱式变电站（简称箱式变）进行升压，风电机组与箱式变的接线方式采用一机一变的单元接线方式。（P3634）"},
    {"id": "sp-364", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "集电线路架设方式与长度", "required_value": "35kV集电线路采用架空方式（个别位置采用电缆直埋），集电线路长度共26.81km", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "35 kV 集电线路采用架空方式（个别位置采用电缆直埋），集电线路长度共 26.81  km。（P3635）"},
    {"id": "sp-365", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "直埋及塔筒内电缆范围与光缆同沟", "required_value": "直埋及塔筒内电缆主要有发电机出口至箱式变电站、箱式变电站至35kV架空线杆塔以及终端杆至升压站段；通信光缆与电力电缆同沟埋设", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "本风场直埋及塔筒内电缆主要有发电机出口至箱式变电站、箱式变电站至35kV架空线杆塔以及终端杆至升压站段，通信光缆与电力电缆同沟埋设。（P3636）"},
    {"id": "sp-366", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "人工接地网与接地装置材料", "required_value": "每台风力发电机组基础周围铺设人工接地网，一台风机与一台箱式变共同组成一个独立接地网；接地装置推荐采用热镀锌扁钢、热镀锌圆钢接地极和接地模块", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "在每台风力发电机组基础周围铺设人工接地网，一台风机与一台箱式变共同组成一个独立接地网。接地装置推荐采用热镀锌扁钢、热镀锌圆钢接地极和接地模块。（P3637）"},
    {"id": "sp-367", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "升压站设计原则与综合自动化系统", "required_value": "220kV升压站按标准升压站原则设计，考虑实现无人值班、少人值守运行方式；安装综合自动化系统，具有保护、控制、通信、测量等功能，实现风电场及220kV升压站全功能自动化管理及与调度端遥测遥信功能", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "220kV升压站按照标准升压站原则设计，同时考虑可实现无人值班、少人值守的运行方式。升压站内安装有综合自动化系统，具有保护、控制、通信、测量等功能，可实现风电场及220kV升压站的全功能自动化管理，实现风电场与调度端的遥测、遥信功能及其他功能。（P3638）"},
    {"id": "sp-368", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "动态无功补偿装置配置", "required_value": "220kV升压站在220kV主变35kV侧安装1套动态无功补偿装置，容量±30Mvar", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "根据接入系统设计报告，本 220 kV升压站在 220 kV 主变35kV侧安装 1 套动态无功补偿装置，无功补偿装置的容量为±30Mvar。（P3639）"},
    {"id": "sp-369", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "风电机组监控方式", "required_value": "风电机组监控分现地监控和集中监控两种方式；现地可单机控制、监视保护动作信号及测量参数，集中可在中控室对各台机组监控", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "本风电场的风电机组监控分为现地监控和集中监控两种方式。现地监控方式下可在现地对风电机组进行单机控制、监视保护动作信号及有关测量参数；集中监控方式下可在中控室对各台风电机组进行监控。（P3640）"},
    {"id": "sp-370", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "继电保护及安全自动装置技术要求", "required_value": "继电保护和安全自动装置全部采用微机型保护装置，保护装置出口一律采用继电器无源接点方式，应满足可靠性、选择性、灵敏性和速动性要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本风电场的继电保护和安全自动装置全部采用微机型保护装置，保护装置出口一律采用继电器无源接点的方式，继电保护和安全自动装置应满足可靠性、选择性、灵敏性和速动性的要求。（P3641）"},
    {"id": "sp-371", "clause": "第五章4.3.1概述", "page": "n/a-无分页",
     "requirement": "图像监控、安全警卫与语音通信配置", "required_value": "220kV升压站工程设置图像监控及安全警卫系统；各风电机组之间、塔顶与地面之间、机组与控制室之间语音通信选用无线对讲机及公网手机，无线对讲机暂按10部配置", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "220 kV升压站工程需要设置图像监控及安全警卫系统。各风力发电机组之间，风力发电机组塔顶与地面之间，风力发电机组与控制室之间的语音通信方式，选用无线对讲机及公网手机的通信方式，无线对讲机暂按 10 部配置。（P3642）"},
    {"id": "sp-372", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "风电机组选型原则与智能化能力", "required_value": "按技术领先、性能可靠、智能化高原则确定风电机组，具有控制系统智能化技术（智能控制、自我修正、远程诊断、智能检测、全场协同控制）；正常采用集中监控方式，由中控室运行人员通过人机接口对全场机组集中远方监视和监控", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "按照“技术领先、性能可靠、智能化高”原则确定风电机组，风电机组具有控制系统智能化技术，具有智能控制、自我修正、远程诊断、智能检测以及全场协同控制能力。风电机组正常采用集中监控方式，由中控室运行人员，通过风电机组计算机监控系统的人机接口，对风电场内所有风电机组进行集中远方监视和监控。（P3645）"},
    {"id": "sp-373", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "风机类型", "required_value": "3叶片、水平轴、变速变浆距、异步发电机", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "1）风机类型：3叶片、水平轴、变速变浆距、异步发电机；（P3647）"},
    {"id": "sp-374", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "设计使用寿命与保修期", "required_value": "设计使用寿命25年；风机保修期60个月", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "2）设计使用寿命：25年；风机保修期：60个月。（P3648）"},
    {"id": "sp-375", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "温度要求", "required_value": "在－40℃~50℃范围内不损坏，至少在－35℃~40℃范围内能够正常运行", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "3）温度要求：风力发电机组在－40℃~50℃范围内不损坏，至少在－35℃~40℃范围内能够正常运行。（P3649）"},
    {"id": "sp-376", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "风机设计标准与优化布置", "required_value": "风机设计符合IEC标准；根据风资源情况及地形图等资料进行优化布置，可选用同容量不同叶片长度和不同轮毂高度风机以获得最大发电效益", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "4）风机设计符合IEC标准。承包商根据风资源情况及地形图等资料进行优化布置，可选用同容量不同叶片长度和不同轮毂高度风机，以获得最大发电效益。（P3650）"},
    {"id": "sp-377", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "可靠性考核", "required_value": "风力发电机组的可靠性进行考核", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "5）风力发电机组的可靠性进行考核。（P3651）"},
    {"id": "sp-378", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "可利用率保证值", "required_value": "≥98%（风电场）；单台机组≥96%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "缺陷责任期内，应保证风电场的可利用率≥98％，单台机组可利用率≥96％；（P3652）"},
    {"id": "sp-379", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "可利用率扣款条款", "required_value": "风机在缺陷责任期平均可利用率≥98%，每低1%扣除风电机组设备总价1%；单台≥96%，每低1%扣除该台设备合同价1%；两者不同时计算，执行金额较高的一项", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风机在缺陷责任期的平均可利用率应≥98%，每低1%，扣除本合同中风电机组设备总价1%；单台可利用率≥96%，每低1%，扣除该台设备合同价的1%；两者不同时计算，执行金额较高的一项。（P3653）"},
    {"id": "sp-380", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "可利用率不达标更换机组", "required_value": "如单台机组可利用率低于96%，发包人可选择由承包人负担全部费用更换一台新的机组直至可利用率满足要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "如单台机组可利用率低于96%，则发包人可选择由承包人负担全部费用更换一台新的机组直至可利用率满足要求为止。（P3654）"},
    {"id": "sp-381", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "功率曲线保证值与发电量违约金", "required_value": "缺陷责任期内功率曲线保证值应大于或等于保证功率曲线为基础计算出的风机发电量的96%；每台风机发电量低于保证值1个百分点支付该台设备合同价格1%违约金；该批次出现2台机不满足保证发电量的96%，负责更换该批次机组直至满足发电量考核要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "在缺陷责任期内, 承包人对功率曲线的保证值应大于或等于保证功率曲线为基础计算出的风机发电量的96%，每台风机发电量低于保证值1个百分点，承包人支付该台设备合同价格1%的违约金。如果该批次出现2台机不满足保证发电量的96%，承包人负责更换该批次机组直至满足发电量考核要求。（P3656）"},
    {"id": "sp-382", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "保证功率曲线定义依据", "required_value": "保证功率曲线指卖方提供的风机计算功率曲线是依照ISO2533、N.N标准的空气密度1.225kg/m3条件下的功率曲线", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "保证功率曲线指卖方提供的风机计算功率曲线是依照ISO2533，N.N标准的空气密度1.225kg/m3条件下的功率曲线。（P3657）"},
    {"id": "sp-383", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "功率曲线违约金与更换条款", "required_value": "每台风电机组验证的功率曲线每低于功率曲线保证值1个百分点，支付该台设备合同价格1%违约金；该批次出现2台机不满足保证功率曲线的96%，负责更换该批次机组直至满足功率曲线性能考核要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "每台风电机组验证的功率曲线每低于功率曲线保证值1个百分点，承包人支付该台设备合同价格1%的违约金。如果该批次出现2台机不满足保证功率曲线的96%，承包人负责更换该批次机组直至满足功率曲线性能考核要求。（P3658）"},
    {"id": "sp-384", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "功率曲线疑问测试权与结果认可", "required_value": "对任何一台机组的功率曲线有疑问，发包人有权在缺陷责任期内提出并聘请国际知名测试机构（如Garrad Hassan、PB Power或MEASNET成员）根据IEC 61400-12标准测量功率曲线，此测试不应对缺陷责任期的进行产生影响，承包商应对测试结果认可", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "如对任何一台机组的功率曲线有疑问，发包人有权在缺陷责任期内提出,并聘请一家国际知名的测试机构(如Garrad Hassan, PB Power，或MEASNET成员)根据IEC 61400-12标准测量功率曲线,此测试不应对缺陷责任期的进行产生影响。承包商应对测试结果认可。（P3659）"},
    {"id": "sp-385", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "功率曲线测试费用归属", "required_value": "测试费用先暂由发包人负责，如果测试结果表明该机组没有达到功率曲线的保证值，测试的费用由承包人负责", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "测试费用先暂由发包人负责，如果测试的结果表明该机组没有达到功率曲线的保证值，测试的费用由承包人负责。（P3665）"},
    {"id": "sp-386", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "备品备件和易耗品责任", "required_value": "风机从安装、调试至质量保证期结束期间的备品备件和易耗品，全部由承包人负责", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风机从安装、调试至质量保证期结束期间的备品备件和易耗品，全部由承包人负责。（P3667）"},
    {"id": "sp-387", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "随机备品备件供应要求", "required_value": "供应风电机组的同时提供在品种和数量上足够使用五年的随机备品备件，数量和品种根据项目规模、所在地自然环境特点及投标方对合同设备的经验确定，备品备件及清单应与风电机组同时交付", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "供应风电机组的同时，承包人应提供在品种上和数量上足够使用五年的随机备品备件，提供的备品备件的数量和品种应根据项目的规模、项目所在地的自然环境特点以及投标方对合同设备的经验来确定，备品备件及相应的清单应与风电机组同时交付。（P3669）"},
    {"id": "sp-388", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "运行维护工具与安全带配置", "required_value": "提供用于安装、调试、运行和维护所需的完整工具及运行维护人员的安全装置；提供安全带和防跌落保护装置，安全带为全身形（肩部、腿部和腰皮带），数量按10套/50MW项目提供，不足50MW项目也提供10套；每副安全带配备2套安全系索", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "a）运行维护工具：承包人应提供用于安装、调试、运行和维护所需的完整工具及运行维护人员的安全装置等。应提供安全带和防跌落保护装置。安全带应是全身形的，包括肩部，腿部和腰皮带，数量按10套/50MW项目提供，不足50MW项目均也提供10套。每副安全带应配备2套安全系索。（P3671）"},
    {"id": "sp-389", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "吊装安装工具供应", "required_value": "提供两套专用于风电机组及塔架卸车、安装吊装使用的吊装工具和辅助工具，工具应为崭新、未使用过", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "b)吊装安装工具：投标方应提供两套专用于风电机组及塔架卸车、安装吊装使用的吊装工具和辅助工具，这些工具应当是崭新，未使用过的。（P3672）"},
    {"id": "sp-390", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "风场年平均可利用率保证值", "required_value": "≥98%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "整个风场风电机组的年平均可利用率≥98%；（P3675）"},
    {"id": "sp-391", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "单台年平均可利用率保证值", "required_value": "≥96%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场内每台风电机组的年平均可利用率≥96%；（P3676）"},
    {"id": "sp-392", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "机组平均功率曲线保证值K", "required_value": "≥97%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "整个风电场内机组的平均功率曲线保证值(K)≥97%（P3677）"},
    {"id": "sp-393", "clause": "第五章4.3.2风力发电机组", "page": "n/a-无分页",
     "requirement": "单台功率曲线保证值K", "required_value": "≥95%", "unit": "%",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "每台风机机组的功率曲线保证值(K)≥95%。（P3678）"},
    # —— A2c：4.3.3 塔筒（P3680–P3721 共 39 行；P3682 待填模板行「节段数/长度/重量：
    #     ___」不抽；P3681 样式字段被误抽为「样式 四号 首行缩进…」、P3692–P3699
    #     样式「段」、P3706–P3708 样式「Normal_7」、P3721「Body Text」均已登记）——
    {"id": "sp-394", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒型式与组成", "required_value": "塔筒采用钢混塔筒，包括塔筒本体、预应力锚索及锚具、塔筒入口台阶（双扶手阶梯、平台等）", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "1）塔筒采用钢混塔筒，包括塔筒本体、预应力锚索及锚具、塔筒入口台阶（双扶手阶梯、平台等）；（P3680）"},
    {"id": "sp-395", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒样式设计与标准符合", "required_value": "根据风况条件及风资源参数综合考虑发电量收益和风电机组及塔筒载荷安全性确定塔筒样式；塔筒设计符合GL规范要求，制造和材料规范满足国际通用或中国相关标准，适合当地运输和安装条件；塔筒设计方案应包括对应中国标准的材料标准、工艺标准、检验标准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "应答人应根据风电场风况条件及风资源参数，综合考虑发电量收益和风电机组及塔筒载荷安全性来确定投标机型的塔筒样式。塔筒的设计应符合GL规范中的要求制造和材料规范应满足国际通用或中国相关标准的要求，同时还应适合当地运输和安装条件。应答人提供的塔筒设计方案中应包括对应中国标准的材料标准、工艺标准、检验标准。（P3681）"},
    {"id": "sp-396", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒内附件", "required_value": "各层平台、支撑、沙筒、安全钢索、冷却器安装支架、电动葫芦悬挂梁、塔筒门、直爬梯固定支撑、灭火器；塔筒所有附件安装使用的螺栓和螺母及垫片等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "3）内附件：各层平台、支撑、沙筒、安全钢索、冷却器安装支架、电动葫芦悬挂梁、塔筒门、直爬梯固定支撑、灭火器；塔筒所有附件安装使用的螺栓和螺母及垫片等；（P3683）"},
    {"id": "sp-397", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒电气系统附件", "required_value": "含电缆及光缆的固定托架、塔筒内照明灯、插座、照明电缆、接地电缆、电缆夹块", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "4）电气系统：含电缆及光缆的固定托架、塔筒内照明灯、插座、照明电缆、接地电缆、电缆夹块；（P3684）"},
    {"id": "sp-398", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒其他附件", "required_value": "电梯、安全导轨及滑块、电动葫芦、感温感烟探头、逃生装置等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "5）其他：电梯、安全导轨及滑块、电动葫芦、感温感烟探头、逃生装置等。（P3685）"},
    {"id": "sp-399", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "法兰材料与整体锻造", "required_value": "所有法兰均采用整体锻造，材料Q345E；筒体板材只能使用高级优质、热轧低合金高强度结构钢", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "6）所有法兰均采用整体锻造，材料：Q345E；筒体板材只能使用高级优质、热轧低合金高强度结构钢。（P3686）"},
    {"id": "sp-400", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒发包人标识", "required_value": "塔筒中上部一侧需有发包人标识，塔筒上标识企业名称应与发包人协商确定，出厂前标识完整", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "7）塔筒中上部一侧需有发包人标识，塔筒上标识企业名称，应与发包人协商确定。出厂前标识完整。（P3687）"},
    {"id": "sp-401", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒监测与控制技术", "required_value": "采用共振隔离与极限荷载、疲劳荷载控制、抑制涡流激振、在线基础沉降监测、在线晃动监测、振动监测、在线塔架生命评估等技术", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "8）塔筒采用共振隔离与极限荷载、疲劳荷载控制、抑制涡流激振、在线基础沉降监测、在线晃动监测、振动监测、在线塔架生命评估等技术。（P3688）"},
    {"id": "sp-402", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "扰流环供货", "required_value": "塔筒设备供货时应提供满足施工要求的扰流环", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒设备供货时应提供满足施工要求的扰流环。（P3690）"},
    {"id": "sp-403", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒内防跌落、安全爬梯与照明", "required_value": "塔筒内应有防跌落装置、电梯安全爬梯、一定数量的中间平台和照明设备，应保证在风电机组停机或与电网断开时也有照明", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒内应有防跌落装置、电梯安全爬梯、一定数量的中间平台和照明设备，应保证在风电机组停机或与电网断开时也有照明。（P3691）"},
    {"id": "sp-404", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒内电梯设置", "required_value": "塔筒设备内应设置方便人员运维等应用的电梯", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒设备内应设置方便人员运维等应用的电梯（P3692）"},
    {"id": "sp-405", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔架门防水设计", "required_value": "塔架门要求防水设计", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔架门要求防水设计。（P3693）"},
    {"id": "sp-406", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "电气设备布置于塔架或机舱内", "required_value": "所有电气设备（包括变频器、主控柜等）均需要布置于塔架或机舱内，不得于塔架外单独布置；设计时应确保设备更换可进出塔架门", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "所有电气设备，包括变频器、主控柜等均需要布置于塔架或机舱内，不得于塔架外单独布置。设计时应确保设备更换可进出塔架门。（P3694）"},
    {"id": "sp-407", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "底节塔架设备安装平台", "required_value": "底节塔架设备安装平台应与塔架壁连接为一体，满足从该顶部吊入安装就位的工艺要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "底节塔架设备安装平台应与塔架壁连接为一体，满足从该顶部吊入安装就位的工艺要求。（P3695）"},
    {"id": "sp-408", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔架底部临时应急平台", "required_value": "塔架底部宜设立临时应急平台，用于特殊情况下维护工作人员的休息", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔架底部宜设立临时应急平台，用于特殊情况下维护工作人员的休息。（P3696）"},
    {"id": "sp-409", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔架内运行检修工具与易损配件库", "required_value": "塔架内应设置常用的运行检修工具和易损配件库", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔架内应设置常用的运行检修工具和易损配件库。（P3697）"},
    {"id": "sp-410", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔架LOGO与安全标识喷涂", "required_value": "塔架上需喷招标人公司LOGO、设备编号、安全标识，颜色、字体、大小、喷涂位置在合同执行阶段由招标人确定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔架上需喷招标人公司LOGO，设备编号、安全标识，颜色、字体、大小、喷涂位置在合同执行阶段由招标人确定。（P3698）"},
    {"id": "sp-411", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔架板材供应商要求", "required_value": "制作塔架的板材需选用国内一线钢厂、混凝土塔筒厂家", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "制作塔架的板材需选用国内一线钢厂、混凝土塔筒厂家。（P3699）"},
    {"id": "sp-412", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "安全爬梯永久固定", "required_value": "安全爬梯应永久固定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "安全爬梯应永久固定。（P3700）"},
    {"id": "sp-413", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒及机舱照明装置", "required_value": "塔筒及机舱应设照明装置，包括工作照明、引导照明和应急照明；塔筒内照明灯具安装位置应便于检修维护，以确保攀爬塔筒和在机舱工作的安全", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒及机舱应设照明装置，包括工作照明、引导照明和应急照明。塔筒内照明灯具安装位置应便于检修维护，以确保攀爬塔筒和在机舱工作的安全。（P3701）"},
    {"id": "sp-414", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒防腐措施与标准", "required_value": "塔筒使用满足区域海拔高度、湿度要求，应有良好的防腐措施，并不低于国家、行业标准；因频率校核需要，必要时投标人应对塔架进行相应优化", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒使用满足区域海拔高度高度，湿度要求，应有良好的防腐措施，并不低于国家，行业标准。在设计单位对风机基础进行设计过程中，因频率校核的需要，必要时投标人还应对塔架进行相应的优化。（P3702）"},
    {"id": "sp-415", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "法兰品牌要求", "required_value": "法兰品牌采用国内知名品牌产品", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "法兰：法兰品牌采用国内知名品牌产品。（P3703）"},
    {"id": "sp-416", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "油漆品牌要求", "required_value": "油漆品牌采用国内知名品牌产品", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "油漆，油漆品牌采用国内知名品牌产品；（P3704）"},
    {"id": "sp-417", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒电缆防火封堵", "required_value": "塔筒设计时应考虑电缆防火封堵要求，满足行业相关要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒设计时，应考虑电缆防火封堵要求，满足行业相关要求。（P3705）"},
    {"id": "sp-418", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒加工防腐防护设计寿命", "required_value": "风力发电机组整机及零部件的防腐防护为长期防腐防护，需具备耐久性，防腐设计寿命年限为20年；防腐涂层体系设计、材料选择、表面处理、涂装工艺、施工操作需满足安全健康环保等要求，满足涂层检验、验收和型式试验要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒加工相关技术要求：风力发电机组整机及零部件的防腐防护为长期防腐防护，需具备耐久性，整机及零部件的防腐设计寿命年限为20 年。风力发电机组整机零部件的防腐涂层体系设计、材料选择、表面处理、涂装工艺、 施工操作需满足安全健康环保等要求，需满足涂层检验、验收和型式试验要求。（P3706）"},
    {"id": "sp-419", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒和基础稳定支撑要求", "required_value": "塔筒和基础应在风电场可能遇到的外部条件、设计工况和载荷情况下稳定地支撑风轮和机舱（包括发电机和传动系统），以保证风电机组安全正常运行", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒和基础应在风电场可能遇到的外部条件、设计工况和载荷情况下稳定地支撑风轮和机舱(包括发电机和传动系统)，以保证风电机组安全正常运行。（P3707）"},
    {"id": "sp-420", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒和基础强度要求", "required_value": "塔筒和基础应具有足够的强度、承受作用在风轮和塔筒上的静载荷和动载荷", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "塔筒和基础应具有足够的强度、承受作用在风轮和塔筒上的静载荷和动载荷。（P3708）"},
    {"id": "sp-421", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "钢质塔筒板厚、筒体材料与混凝土标号", "required_value": "钢质塔筒设计板厚按GB/T 709-2019标准圆整，筒体材料不低于Q355材质；混凝土塔筒标号不得小于C80（具体以设计计算为准）", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）钢质塔筒设计的板厚应按照GB/T 709-2019标准圆整，筒体材料不低于Q355材质。混凝土塔筒的标号不得小于C80，具体以设计计算为准。（P3710）"},
    {"id": "sp-422", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒内防跌落、安全爬梯与LED防爆照明", "required_value": "塔筒内应设有防跌落装置、安全爬梯、一定数量的中间平台和LED防爆照明设备，应保证在风机停机或与电网断开时也有照明", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）塔筒内应设有防跌落装置、安全爬梯、一定数量的中间平台和LED防爆照明设备，应保证在风机停机或与电网断开时也有照明。（P3711）"},
    {"id": "sp-423", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "安全爬梯材料与防坠落装置", "required_value": "安全爬梯应永久固定，采用热镀锌钢制材料；防坠落装置应采用安全绳", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）安全爬梯应永久固定。安全爬梯应采用热镀锌钢制材料，防坠落装置应采用安全绳。（P3712）"},
    {"id": "sp-424", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒顶层平台防漏油设施", "required_value": "塔筒顶层平台应有防漏油设施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（4）塔筒顶层平台应有防漏油设施。（P3713）"},
    {"id": "sp-425", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒门钢梯、安全机构与抗风固定", "required_value": "塔筒门外应设有钢梯，钢梯应设双扶手；塔筒门设安全机构以防止未经授权进入塔筒并防止人员在塔筒内部被锁；塔筒门设固定装置，在风速达到15m/s时确保已开启的门不变形、不损坏", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（5）塔筒门外应设有钢梯，钢梯应设双扶手。塔筒门设安全机构，以防止未经授权进入塔筒，同时防止人员在塔筒内部被锁。塔筒门设固定装置，在风速度达到15 m/s时，确保已开启的门不变形，不损坏。（P3714）"},
    {"id": "sp-426", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒门下电缆穿管预留", "required_value": "塔筒门下应预留至箱变的电缆穿管", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（6）塔筒门下应预留至箱变的电缆穿管。（P3715）"},
    {"id": "sp-427", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "平台护栏和踏板", "required_value": "所有平台须设有适当的护栏和踏板", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（7）所有平台须设有适当的护栏和踏板。（P3716）"},
    {"id": "sp-428", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "塔筒及机舱照明与电源插座", "required_value": "塔筒及机舱应设照明装置（工作照明、引导照明和应急照明）；应急照明包括一整套蓄电池组和逆变器；在机舱、塔筒底部及每个休息平台均应提供交流380V及220V双电源插座", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（8）塔筒及机舱应设照明装置，包括工作照明、引导照明和应急照明。塔筒内照明灯具安装位置应便于检修维护，以确保攀爬塔筒和在机舱工作的安全。应急照明包括一整套蓄电池组和逆变器。在机舱、塔筒底部及每个休息平台均应提供交流380V及220V双电源插座。（P3717）"},
    {"id": "sp-429", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "主电缆设计对爬梯安全影响", "required_value": "如果塔筒内爬梯用于支撑从机舱发电机至塔筒底部的主电缆及附件，电缆必须进行适合风机特殊使用要求的设计；电缆不得对爬梯及其相关设备的使用安全造成影响；电缆夹设置位置应便于检修维护", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（9）如果塔筒内爬梯用于支撑从机舱发电机至塔筒底部的主电缆及附件，则电缆必须进行适合风机特殊使用要求的设计。电缆不得对爬梯及其相关设备的使用安全造成影响。电缆夹设置位置应便于检修维护。（P3718）"},
    {"id": "sp-430", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "防坠电缆支架", "required_value": "采用防坠电缆支架", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（10）采用防坠电缆支架。（P3719）"},
    {"id": "sp-431", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "预应力锚索抽样复检要求", "required_value": "预应力锚索数量、尺寸规格根据塔筒底部荷载进行设计，每批次均须抽样并按技术规范书中检测报告的项目内容，在本风电场由监理取样后送国家承认资质的部门进行复检", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（11）预应力锚索数量、尺寸规格根据塔筒底部荷载进行设计，每批次均须抽样并按技术规范书中检测报告的项目内容，在本风电场由监理取样后送国家承认资质的部门进行复检。（P3720）"},
    {"id": "sp-432", "clause": "第五章4.3.3塔筒", "page": "n/a-无分页",
     "requirement": "钢混塔架详细技术要求依据", "required_value": "本项目钢混塔架的详细技术要求可见风机、塔筒技术协议", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（12）本项目钢混塔架的详细技术要求可见风机、塔筒技术协议。（P3721）"},
    # —— A2d：4.3.4 箱变（P3723–P3769 共 40 行；P3724/P3734/P3738/P3740/P3743/
    #     P3745/P3751 为「N）xxx要求」引导标题不抽）——
    {"id": "sp-433", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱式变压器型式与配置", "required_value": "35kV干式箱式变压器；35kV侧装设隔离开关-断路器-接地开关组合电器、避雷器、带电显示器等，低压侧装设框架断路器、浪涌保护器等", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "本项目采用35kV干式箱式变压器。箱式变电站35kV侧装设隔离开关-断路器-接地开关组合电器、避雷器、带电显示器等，低压侧装设框架断路器、浪涌保护器等。（P3723）"},
    {"id": "sp-434", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变结构、通风温升与除湿防爆", "required_value": "内部布置按标准设计图纸设定；自然通风，额定和1.5倍短时过负荷运行状态下温升符合《电网公司输变电工程通用设备》规定；箱站内部采取除湿、防爆和防凝露措施；站用电控制箱具有照明、检修维护等功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）干式箱变其内部布置结构按标准设计图纸要求设定。箱式变电站采用自然通风方式，自然通风条件下，在额定和1.5倍短时过负荷运行状态下的温升，应符合《电网公司输变电工程通用设备》规定。箱站内部应采取除湿、防爆和防凝露措施。站用电控制箱应具有照明、检修维护等功能。（P3725）"},
    {"id": "sp-435", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "高压开关柜选型与五防连锁、核相装置", "required_value": "高压设备选用环网式或终端式开关柜，结构紧凑体积小、安装方便、性能可靠、少维护；具有完备的五防连锁功能，连锁装置强度满足操作要求；开关柜内套管、隔板、活门、绝缘件等附件为耐火阻燃材料；负荷开关组合电器熔断器安装位置便于更换；负荷开关柜面板安装带电显示及核相装置并提供核相装置型号与参数；核相器及操作手柄作为必备附件每站一套", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）高压设备选用环网式或终端式开关柜；产品结构紧凑体积小、安装方便、性能可靠、少维护。具有完备的五防连锁功能，连锁装置强度满足操作的要求。开关柜内套管、隔板、活门、绝缘件等所有附件应为耐火阻燃材料。负荷开关组合电器的熔断器安装位置应便于运行人员更换熔断器。负荷开关柜其面板应安装带电显示及核相装置，提供核相装置的型号与参数。核相器及操作手柄作为必备附件应每站一套。（P3726）"},
    {"id": "sp-436", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "环网柜柜体钢板与表面处理", "required_value": "环网柜柜体钢板采用冷轧钢板或敷铝锌板，表面经酸洗、磷化处理后静电喷塑；柜内安装件均经镀锌、钝化处理，提高三防性能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）环网柜柜体钢板均应采用冷轧钢板或敷铝锌板，表面经过酸洗、磷化处理后静电喷塑，柜内的安装件均经镀锌，钝化处理，提高“三防”性能。（P3727）"},
    {"id": "sp-437", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱体材料、防腐与使用寿命", "required_value": "箱体宜选用高强度、使用寿命长的阻燃性非金属材料制成（具体以图纸为准）；当选用冷轧钢板时箱体表面应喷砂、喷锌、喷涂优质防腐涂料，保证箱变25年不锈蚀；箱体采用双层保温结构，外围四角圆角工艺，外部机械撞击不小于20J；箱站设计使用寿命不应小于25年", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（4）箱变箱体宜选用高强度、使用寿命长的阻燃性非金属材料制成，与外部环境相协调，美化环境（具体以图纸为准）。当选用冷轧钢板时，箱体表面应进行喷砂、喷锌、喷涂优质防腐涂料，保证箱变25年不锈蚀。箱体采用双层保温结构，外围四角采用圆角工艺，外部机械撞击不小于20J。箱站设计使用寿命不应小于25年。（P3728）"},
    {"id": "sp-438", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变顶盖结构", "required_value": "顶盖采用双层、斜顶结构，有隔热作用，减少日照引起的变电站室内温度升高，顶部承受负荷能力强，确保站顶不渗水、滴漏", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（5）顶盖采用双层，斜顶结构，有隔热作用，减少日照引起的变电站室内温度升高，顶部承受负荷能力强，并确保站顶不渗水、滴漏。（P3729）"},
    {"id": "sp-439", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变外壳防护等级", "required_value": "不低于IP65", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "2）箱变外壳防护等级：不低于IP_65_。（P3730）"},
    {"id": "sp-440", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变使用寿命", "required_value": "大于25年", "unit": "年",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "3）箱变使用寿命大于25年。（P3731）"},
    {"id": "sp-441", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "设备海拔修正计算", "required_value": "根据设备安装位置的实际海拔高度对设备的技术参数及设备外绝缘进行修正计算", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "4）箱式变电站内所有设备应根据设备安装位置的实际海拔高度对设备的技术参数及设备外绝缘进行修正计算。（P3732）"},
    {"id": "sp-442", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "设备持久耐用性", "required_value": "全部设备应能持久耐用，即使在技术规范中没有明显提出，也应满足在实际运行工况下作为一个完整产品一般应能满足的全部要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "5）全部设备应能持久耐用，即使在技术规范中没有明显地提出，也应满足在实际运行工况下作为一个完整产品一般应能满足的全部要求。（P3733）"},
    {"id": "sp-443", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "接线端子配置", "required_value": "设备应配备接线端子，尺寸满足回路额定电流及联接要求，并提供铜质或不锈钢制造的螺栓、螺帽及防松垫圈", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）设备应配备接线端子，其尺寸应以满足回路的额定电流及联接要求，并应提供铜质或不锈钢制造的螺栓、螺帽及防松垫圈。（P3735）"},
    {"id": "sp-444", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "接线端子镀锡与套管端子防护", "required_value": "接线端子接触面应镀锡；变压器套管端子配置旋入式接线端子并加装绝缘防护罩", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）接线端子的接触面应镀锡，变压器套管端子要求配置旋入式接线端子并加装绝缘防护罩。（P3736）"},
    {"id": "sp-445", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "接地端子与接地连接线", "required_value": "设备接地端子应是螺栓式、适合连接；接地连接线应为铜质，截面与可能流过的短路电流相适应", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）设备的接地端子应是螺栓式，适合于连接。接地连接线应为铜质，其截面应与可能流过的短路电流相适应。（P3737）"},
    {"id": "sp-446", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "接地标志与接地端子数量", "required_value": "变压器主要接地点应有明显接地标志；箱体中应设有不少于两个与接地系统相连的端子，需要接地的高低压电器元件及金属部件均应有效接地", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "变压器主要接地点应有明显的接地标志。箱体中应设有不少于两个与接地系统相连的端子，需要接地的高低压电器元件及金属部件均应有效接地。（P3739）"},
    {"id": "sp-447", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "变压器内部焊接质量", "required_value": "变压器内部焊接应由电弧焊完成，不得发生虚焊、裂缝及其它任何缺陷", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "变压器内部焊接应由电弧焊完成，不得发生虚焊、裂缝及其它任何缺陷。（P3741）"},
    {"id": "sp-448", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱体外螺栓、门轴锁盒与开启角度", "required_value": "箱体外（不含基础）无外露可拆卸的螺栓；所有门轴采用不锈钢材料制作；所有锁盒采用户外铝合金锁盒；所有门向外开、开启角度大于90°并设定位装置，门设计尺寸与所装设备尺寸相配合；箱变外侧立面设置明显安全警告标识和标志", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "9）箱体外（不含基础）无外露可拆卸的螺栓，所有门轴必须采用不锈钢材料制作，所有锁盒采用户外铝合金锁盒。所有的门应向外开，开启角度应大于90°，并设定位装置，门的设计尺寸应与所装用的设备尺寸相配合。箱变外侧立面应设置明显的安全警告标识和标志。（P3742）"},
    {"id": "sp-449", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "设备耐地震设计", "required_value": "设备及设备支座必须按承受地震荷载时能保持结构完整来设计", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "设备及设备支座必须按承受地震荷载时能保持结构完整来设计。（P3744）"},
    {"id": "sp-450", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "运输过程避免受损", "required_value": "应避免在运输过程中受损", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）应避免在运输过程中受损。（P3746）"},
    {"id": "sp-451", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "运输限制参数", "required_value": "运输限制，长、宽、高等参见技术数据表", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）运输限制，长、宽、高等参见技术数据表。（P3747）"},
    {"id": "sp-452", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "运输受损修复替换责任", "required_value": "如因投标人措施不当导致运输过程中设备受损，投标人应负责修复或替换，费用自负", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）如因投标人措施不当，导致运输过程中设备受损，投标人应负责修复或替换，费用自负。（P3748）"},
    {"id": "sp-453", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱式变压器运输包装", "required_value": "箱式变压器运输包装应满足运输方的要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（4）箱式变压器运输包装应满足运输方的要求。（P3749）"},
    {"id": "sp-454", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "运输过程设备清洁", "required_value": "在运输过程中需保持设备内部和外部的清洁", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（5）在运输过程中需保持设备内部和外部的清洁。（P3750）"},
    {"id": "sp-455", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "温度变化耐受性", "required_value": "箱式变压器在使用寿命期内，用户按正常条件使用产品，产品不会因温度变化导致设备出现任何损伤", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）箱式变压器在使用寿命期内，用户按正常条件使用产品，产品不会因温度变化导致设备出现任何损伤。（P3752）"},
    {"id": "sp-456", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "阻燃与绝缘材料特性", "required_value": "产品阻燃性好，绝缘材料具有自动熄火的特性，遇到火源时不产生有害气体", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）产品阻燃性好，绝缘材料具有自动熄火的特性，遇到火源时不产生有害气体。（P3753）"},
    {"id": "sp-457", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变连锁保护功能", "required_value": "箱式变压器自带连锁保护功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）箱式变压器自带连锁保护功能。（P3754）"},
    {"id": "sp-458", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变进线方式与高低压室配置", "required_value": "箱变高、低压室均采用电缆下进线的进线方式；低压绕组配置低压柜，柜内设框架断路器、塑壳式断路器、浪涌保护器、电流互感器等；高压室配置负荷开关熔断器组合电器、避雷器、带电显示器、接地开关、隔离开关等；箱变内配置箱变智能控制单元、温湿度控制器等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（4）箱变高、低压室均采用电缆下进线的进线方式。低压绕组配置低压柜，柜内设框架断路器，塑壳式断路器，浪涌保护器，电流互感器等。箱变高压室配置负荷开关熔断器组合电器，避雷器，带电显示器，接地开关，隔离开关等。箱变内配置 箱变智能控制单元、温湿度控制器等。（P3755）"},
    {"id": "sp-459", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变绕组材料", "required_value": "箱变绕组必须为铜质材料", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（5）箱变绕组必须为铜质材料。（P3756）"},
    {"id": "sp-460", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变防护结构与环境适应性", "required_value": "本地区夏季炎热、冬季寒冷、夏季多雨，箱变需经过严格设计及试验验证，具备合理的防护结构、防潮结构、防风沙结构以及耐寒、耐高温以及防腐、耐潮等性能，以满足恶劣环境条件下正常安全运行要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（6）本地区夏季炎热、冬季寒冷、夏季多雨，箱变需经过严格设计及试验验证， 具备合理的防护结构、防潮结构、防风沙结构以及耐寒、耐高温以及防腐、耐潮等性能，以满足恶劣环境条件下正常安全运行要求。（P3757）"},
    {"id": "sp-461", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变除湿与调温装置", "required_value": "箱式变电器箱体内设除湿装置，设调温元件，保证设备的不同环境下正常运行", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（7）箱式变电器箱体内设除湿装置，设调温元件，保证设备的不同环境下正常运行。（P3758）"},
    {"id": "sp-462", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变信号引出与通信型式", "required_value": "箱式变电器的高、低压开关动作、保护等信号应能集中引出，提供给相连接的箱变测控单元；箱变测控装置支持多种通信型式，RS485、光通信等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（8）箱式变电器的高、低压开关动作、保护等信号应能集中引出，提供给相连接的箱变测控单元。箱变测控装置支持多种通信型式，RS485、光通信等。（P3759）"},
    {"id": "sp-463", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "UPS户外型与供电时长", "required_value": "UPS采用户外型，应适应当地环境温度，不因低温而亏电，并应与高压侧具备连跳及远程开关机功能；UPS电源在当地环境下（抗低温）满足2小时供电要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（9）UPS采用户外型，应适应当地环境温度，不因低温而亏电，并应与高压侧具备连跳及远程开关机功能。UPS电源在当地环境下（抗低温），满足2小时供电要求。（P3760）"},
    {"id": "sp-464", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "蓄电池户外型要求", "required_value": "蓄电池采用户外型蓄电池，应适应当地环境温度，不因低温而亏电", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（10）蓄电池采用户外型蓄电池，应适应当地环境温度，不因低温而亏电。（P3761）"},
    {"id": "sp-465", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "UPS亏电时手动合闸功能", "required_value": "箱变跳闸后，在UPS由于亏电无法正常使用时，高压侧具备手动合闸功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（11）箱变跳闸后，在UPS由于亏电无法正常使用时，高压侧具备手动合闸功能。（P3762）"},
    {"id": "sp-466", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "GPS时间同步要求", "required_value": "综保装置和后台监控系统应同时具备GPS时间同步要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（12）综保装置和后台监控系应同时具备GPS时间同步要求。（P3763）"},
    {"id": "sp-467", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变通讯双环网与光纤盒预留口", "required_value": "箱变通讯应具备双环网功能，光纤盒预留口不少于6个", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（13）箱变通讯应具备双环网功能，光纤盒预留口不少6个。（P3764）"},
    {"id": "sp-468", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变箱体密封与防尘", "required_value": "箱变箱体应具有良好的密封性，具备防尘功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（14）箱变箱体应具有良好的密封性，具备防尘功能。（P3765）"},
    {"id": "sp-469", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变低压远控与失电保持", "required_value": "箱变应能实现低压侧的远控功能，且能实现箱变低压失电后，测控装置不能立即失电，造成通讯中断", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（15）箱变应能实现低压侧的远控功能，且能实现箱变低压失电后，测控装置不能立即失电，造成通讯中断。（P3766）"},
    {"id": "sp-470", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变内部主要设备品牌", "required_value": "箱变内部主要设备（断路器、负荷开关、避雷器、互感器、测控装置、UPS）必须为国内一线品牌且经过发包人确认", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（16）箱变内部主要设备（断路器、负荷开关、避雷器、互感器、测控装置、UPS）必须为国内一线品牌且经过发包人确认。（P3767）"},
    {"id": "sp-471", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变能效标准", "required_value": "箱变损耗执行新国标GB 20052-2020中二级及以上能效标准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（17）箱变损耗执行新国标GB 20052-2020中二级及以上能效标准。（P3768）"},
    {"id": "sp-472", "clause": "第五章4.3.4箱变", "page": "n/a-无分页",
     "requirement": "箱变自动灭火装置", "required_value": "箱变应具备自动灭火装置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（18）箱变应具备自动灭火装置。（P3769）"},
