    {"id": "sp-628", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "远动通道主备方式", "required_value": "风电场至河北省调（含备调）、某市调（含备调）的远动通道采用主、备方式，主、备通道采用电力调度数据网通道", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场至河北省调(含备调)、某市调（含备调）的远动通道采用主、备方式，主、备通道采用电力调度数据网通道。（P3951）"},
    {"id": "sp-629", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "远动通信规约", "required_value": "风电场至河北省调（含备调）、某市调（含备调）的远动通信规约采用IEC-60870-5-104规约", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场至河北省调(含备调)、某市调（含备调）的远动通信规约采用IEC-60870-5-104规约。（P3952）"},
    {"id": "sp-630", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "调度数据网设备双套配置", "required_value": "升压站数据网设备应双套配置，主要包括2台路由器、4台接入交换机，分别接入河北省调、某市调接入网", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场升压站数据网设备应双套配置，主要包括2台路由器、4台接入交换机，分别接入河北省调、某市调接入网。（P3955）"},
    {"id": "sp-631", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "调度数据网接入通道与路由", "required_value": "调度数据网接入节点设在电力调度数据网的骨干接点，升压站通过2×2M带宽的通道直接接入骨干节点；每个接入地点的2条通信链路应采用不同的路由", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程调度数据网接入节点设在电力调度数据网的骨干接点,风电场升压站通过2×2M带宽的通道直接接入骨干节点，要求每个接入地点的2条通信链路应采用不同的路由。（P3957）"},
    {"id": "sp-632", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "监控系统与调度中心通信规约", "required_value": "升压站计算机监控系统与调度中心之间的通信协议采用IEC60870-5-104规约", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场升压站计算机监控系统与调度中心之间的通信协议采用IEC60870-5-104规约。（P3958）"},
    {"id": "sp-633", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "电力监控系统安全防护设备配置", "required_value": "配置纵向加密认证装置4台、生产控制大区防火墙2台、入侵检测系统（IDS）1台、恶意代码防护设备1套、运维网关（便携式堡垒机）1台、电力监控系统专用调试终端和移动介质1套，设备型号应与网调要求一致", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据“电力二次系统安全防护规定”的要求，按照“安全分区、网络专用、横向隔离、纵向认证”的基本原则，为保证调度自动化系统安全稳定运行和调度实时数据的安全性，本风电场配置纵向加密认证装置4台、生产控制大区防火墙2台、入侵检测系统（IDS）1台以及恶意代码防护设备1套、运维网关（便携式堡垒机）1台、电力监控系统专用调试终端和移动介质1套，并且设备型号应与网调要求相一致。（P3960）"},
    {"id": "sp-634", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "安全防护设备供电要求", "required_value": "依据国家电网设备〔2018〕979号要求，调度数据网及安全防护设备应具备双电源模块，并采用冗余配置的不间断电源（UPS）或站内直流电源供电", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "依据《国家电网公司十八项电网重大反事故措施（修订版）》（国家电网设备〔2018〕979号）的要求，调度数据网及安全防护设备应具备双电源模块，并采用冗余配置的不间断电源（UPS）或站内直流电源供电。（P3961）"},
    {"id": "sp-635", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "就地采集终端物理防护与纵向加密", "required_value": "根据冀电调〔2023〕28号要求，新能源场站须加强户外就地采集终端（箱变测控装置）的物理防护，强化通信安全；站控系统与终端之间网络通信应部署加密认证装置，实现身份认证、数据加密、访问控制；终端连接的网络设备需采取IP/MAC地址绑定等措施禁止外部设备接入；每台箱变均配置1台微型纵向加密装置，升压站内配置1台千兆纵向加密认证装置和1台防火墙", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据国网河北省电力有限公司关于印发《调度自动化专业及监控系统网络安全专业厂站设计审查要点》的通知（冀电调〔2023〕28号）要求，新能源场站须加强户外就地采集终端（箱变测控装置）的物理防护，强化就地采集终端的通信安全。站控系统与终端之间网络通信应部署加密认证装置，实现身份认证、数据加密、访问控制等安全措施。终端连接的网络设备需采取IP/MAC地址绑定等措施，禁止外部设备的接入，防止单一发电单元的安全风险扩散到站控系统。因此，本期工程风电场的每台箱变均配置1台微型纵向加密装置，升压站内配置1台千兆纵向加密认证装置和1台防火墙。（P3962）"},
    {"id": "sp-636", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "安全防护方案总体目标", "required_value": "确保电力监控系统及电力调度数据网络的安全，抵御黑客、病毒、恶意代码等各种形式的恶意破坏和攻击，特别是抵御集团式攻击，防止电力二次系统的崩溃或瘫痪及由此造成的电力系统事故或大面积停电事故", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电力监控系统安全防护方案的总体目标是：确保电力监控系统及电力调度数据网络的安全，抵御黑客、病毒、恶意代码等各种形式的恶意破坏和攻击，特别是抵御集团式攻击，防止电力二次系统的崩溃或瘫痪，以及由此造成的电力系统事故或大面积停电事故。（P3963）"},
    {"id": "sp-637", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "安全防护原则与安全区划分", "required_value": "原则为“安全分区、网络专用、横向隔离、纵向认证”；监控系统、AGC、AVC、远动系统、时钟同步系统、五防系统等位于安全I区；故障录波装置、网络安全监测装置、电能量采集系统、调度安全II区访问终端、风功率预测及上传等位于安全II区；电能质量在线监测位于安全Ⅳ区", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电力监控系统安全防护的原则为：“安全分区、网络专用、横向隔离、纵向认证”。依据二次系统安全防护的要求，本风电场的监控系统、AGC、AVC、远动系统、时钟同步系统、五防系统等均位于安全I区内；故障录波装置、网络安全监测装置、电能量采集系统、调度安全II区访问终端、风功率预测及上传等均位于安全II区内；电能质量在线监测位于安全Ⅳ区内。（P3964）"},
    {"id": "sp-638", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "远动系统采集与直采直送", "required_value": "远动系统采集部分与场内监控系统合用一套，采用分布式交流采样方案；远动系统连接到监控双以太网上，远动信息直采直送，保证远动信息的实时性和可靠性，通过以太网口连接到数据网接入设备实现与调度数据网连接；同时可接收电网调度指令实现对风机出力的控制", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场升压站远动系统的采集部分与场内监控系统合用一套，采用分布式交流采样方案，满足各级调度要求。远动系统连接到监控双以太网上，远动信息直采直送，保证远动信息的实时性和可靠性，并通过以太网口连接到数据网接入设备上，实现和调度数据网的连接。同时可接收电网调度指令，以实现对风机出力的控制。（P3966）"},
    {"id": "sp-639", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "远动系统一发多收与遥控遥调", "required_value": "远动系统具备一发多收功能，可以和不同主站以不同的规约通信；具备遥测、遥信功能（模拟量、脉冲量、状态量等实时数据的采集、预处理和远传）；同时具备遥控、遥调功能（对遥控、遥调命令的接收、处理和执行）", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "远动系统具备一发多收功能，可以和不同主站，以不同的规约进行通信。系统具备遥测、遥信功能: 即模拟量、脉冲量、状态量等实时数据的采集、预处理和远传功能。同时具备遥控、遥调功能：即对遥控、遥调命令的接收、处理和执行功能。（P3967）"},
    {"id": "sp-640", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "关口计量点与电能表精度", "required_value": "关口计量点设置在220kV并网线开关处，表计为双向双表配置，正向计发电量、反向计用电量，电能表精度0.2S级（三相四线制接线）；35kV集电线路、站用变高压侧、SVG无功补偿装置配置考核表，采用0.2S级单表配置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程关口计量点设置在220kV 并网线开关处为计量点，表计为双向双表配置，正向计发电量、反向计用电量，电能表精度为0.2S 级(三相四线制接线)。35kV 集电线路、站用变高压侧、SVG无功补偿装置配置考核表，采用0.2S 级单表配置。（P3969）"},
    {"id": "sp-641", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "电能量远方终端配置", "required_value": "升压站内配置2套电能量远方终端，用于将本站发电量信息传送至调度采集系统，应具备网络接口要求；升压站至调度采集系统的电量计量通道采用电力调度数据网通道", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "新能源升压站内配置2套电能量远方终端，用于将本站发电量信息传送至调度采集系统，电能量远方终端应具备网络接口要求。升压站至调度采集系统的电量计量通道采用电力调度数据网通道。（P3970）"},
    {"id": "sp-642", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "电量采集装置通信规约", "required_value": "电量采集装置可通过RS485口与电度表通信采集关口电量数据，通过数据通信网向有关部门传送电能信息；通信规约采用DL/T719-2000（即IEC60870-5-102），各项技术要求符合DL/T5202-2004《电能量计量系统设计技术规程》", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场升压站电量采集装置可通过RS485口与电度表通信，采集关口电量数据，电能量采集装置通过数据通信网向有关部门传送电能信息。通信规约采用DL/T719-2000 即IEC60870-5-102，其各项技术要求符合DL/T5202-2004《电能量计量系统设计技术规程》。（P3971）"},
    {"id": "sp-643", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "有功无功控制系统配置", "required_value": "安装一套有功/无功控制系统，一体化设计、集中组屏；通过一套AGC/AVC控制管理终端与主站通信，完成数据采集、数据处理、数据通信、风机有功自动控制、无功/电压闭环控制等功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场升压站安装一套有功/无功控制系统，系统采用一体化设计，集中组屏。通过一套AGC/AVC控制管理终端与主站通信，完成数据采集、数据处理、数据通信、风机有功自动控制、无功/电压闭环控制等功能。（P3973）"},
    {"id": "sp-644", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "风电功率预测系统配置", "required_value": "应配置风电功率预测系统，功率预测信息通过调度数据专网上传至调度端；配置测风塔1座；满足《风电功率预测系统功能规范》要求；具备0h~240h中期、0h~72h短期、15min～10h超短期风电功率预测功能，预测时间分辨率不低于15min", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "新能源升压站应配置风电功率预测系统，功率预测信息通过调度数据专网上传至调度端。配置测风塔1 座，风电功率预测系统的建设需满足《风电功率预测系统功能规范》的要求。风电功率预测系统应具备0h~240h 中期风电功率预测、0h~72h 短期风电功率预测以及15min～10h 超短期风电功率预测功能，预测时间分辨率应不低于15min。（P3975）"},
    {"id": "sp-645", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "网厂交互平台配置", "required_value": "应配置能连接外网的计算机，网速要求100M以上，安装电力市场交易平台客户端、调度管理系统，用于月度电量电费结算、新能源场站与天津市调之间调度/自动化等专业的生产管理工作", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "新能源升压站内应配置能连接外网的计算机，网速要求100M 以上，安装电力市场交易平台客户端、调度管理系统，用于月度电量电费结算、新能源场站与天津市调之间调度、自动化等专业的生产管理工作。（P3977）"},
    {"id": "sp-646", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "电力监控系统安全评估", "required_value": "应对升压站电力监控系统进行安全评估和等级保护测评，并计列相应费用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程应对升压站电力监控系统进行安全评估和等级保护测评，并计列相应费用。（P3979）"},
    {"id": "sp-647", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "风电场惯量响应及一次调频功能", "required_value": "应具备快速控制自身有功功率、提供惯量响应和一次调频的功能，可根据电力系统运行实际需要启用与停用；惯量响应和一次调频功能应配合使用，能实现有功功率的连续平滑调节并将信号上传至调度监控系统；有功功率控制系统及AGC指令应与一次调频相协调，惯量响应和一次调频应能接入同步相量测量装置并上传调度；一次调频能力应符合Q/GDW 1392-2015、《电力系统网源协调技术规范》（DL/T 1870-2018）及GB/T19963.1-2021要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场应具备快速控制自身有功功率，提供惯量响应和一次调频的功能，可根据电力系统运行实际需要启用与停用惯量响应和一次调频功能。风电场的惯量响应和一次调频功能应配合使用，能实现有功功率的连续平滑调节。能实现有功功率的连续平滑调节。并将信号上传至调度监控系统。风电场有功功率控制系统及AGC指令应与一次调频相协调，且风电场的惯量响应和一次调频应能接入同步相量测量装置并上传调度。一次调频能力应符合《风电场接入电网技术规定》（Q/GDW 1392-2015）、《电力系统网源协调技术规范》……（DL/T 1870-2018）及《风电场接入电力系统技术规定》（GB/T19963.1-2021）要求。（P3981；P3982）"},
    {"id": "sp-648", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "一次调频响应时间与偏差", "required_value": "当电力系统频率大于或小于50Hz时，应根据一次调频曲线减少或增加有功输出；一次调频响应滞后时间不大于2s、上升时间不大于9s、调节时间不大于15s、有功功率调节允许偏差不超过±1%PN", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "当电力系统频率大于或小于50Hz时,风电场应根据一次调频曲线减少或增加有功输出,减少或增加功率的限幅可根据实际电力系统要求确定。一次调频响应滞后时间应不大于2s,一次调频上升时间应不大于9s,一次调频调节时间应不大于15s,有功功率调节允许偏差应不超过±1%PN。（P3983）"},
    {"id": "sp-649", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "惯量响应信息接入同步相量装置", "required_value": "惯量响应及一次调频相关信息能够接入同步相量测量装置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "惯量响应及一次调频相关信息能够接入同步相量测量装置。（P3984）"},
    {"id": "sp-650", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "一次调频快速响应装置配置", "required_value": "风电场风机配置1套一次调频快速响应装置，有关信息接入同步向量测量装置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场风机配置1套一次调频快速响应装置，有关信息接入同步向量测量装置。（P3985）"},
    {"id": "sp-651", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "同步相量测量装置（PMU）配置", "required_value": "220kV及以上接入系统的发电工程需配置电力系统相角监测装置（PMU装置），能实现对电力系统相角的实时监测", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据《风电场接入电力系统技术规定》的要求规定，220kV及以上接入系统的发电工程需要配置电力系统相角监测装置（PMU装置），PMU装置能够实现对电力系统相角的实时监测。相角(电压相量的角度、功角)是反映电力系统稳定性能最直接的状态变量，通过对它进行监测并上传省调，经分析处理，能更好地服务于电力系统的稳定和控制。（P3987）"},
    {"id": "sp-652", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "同步相量测量装置采集与上传", "required_value": "按升压站终期规模配置同步相量测量装置柜，采集并网220kV出线三相电流、升压站主变各侧三相电流、35kV进线三相电流（含无功补偿装置）、220kV母线电压、35kV母线电压、220kV出线有功/无功功率、主变各侧有功/无功功率、35kV进线有功/无功功率（含无功补偿装置）、220kV出线开关/主变开关/35kV进线开关状态（含无功补偿装置、PT等设备）；上传至河北省调、某市调，纳入实时数据网络传输；具备次同步震荡监测和长录波功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "按升压站终期规模配置同步相量测量装置柜，采集并网220kV出线三相电流；升压站主变各侧三相电流；35kV进线三相电流（包括无功补偿装置）；220kV母线电压、35kV母线电压；220kV出线有功功率、无功功率；升压站主变各侧有功功率、无功功率；35kV进线有功功率、无功功率（包括无功补偿装置）； 220kV出线开关；升压站主变开关状态；35kV进线开关状态（包括无功补偿装置、PT等设备）。同步相量测量装置上传至河北省调、某市调，纳入实时数据网络传输。具备次同步震荡监测和长录波功能。（P3988）"},
    {"id": "sp-653", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "调度电话通道", "required_value": "风电场至河北省调的2路调度电话通道", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场---河北省调的2路调度电话通道。（P3995）"},
    {"id": "sp-654", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "远动信息传输通道", "required_value": "远动数据采用2×2M数据网通道分别接入河北省调、某市地调数据网双平面", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程远动数据采用2×2M 数据网通道分别接入河北省调、某市地调数据网双平面。（P3997）"},
    {"id": "sp-655", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "电量信息传输通道", "required_value": "电能量信息采用2×2M数据网通道分别接入省电力调度数据网双平面", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程电能量信息采用2×2M数据网通道分别接入省电力调度数据网双平面。（P3999）"},
    {"id": "sp-656", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "调度数据网通道带宽", "required_value": "调度数据网已具备两个汇聚平面，本期工程提供2路通道接入调度数据网I、II平面，每路通道采用4×2M传输带宽", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "调度数据网已经具备两个汇聚平面，本期工程提供2路通道接入调度数据网I、II平面，每路通道采用4×2M传输带宽。（P4001）"},
    {"id": "sp-657", "clause": "第五章4.3.5升压站主要设备", "page": "n/a-无分页",
     "requirement": "保护通道配置", "required_value": "风电场—恒泰220kV汇集站220kV线路每套保护装置均采用专用光纤+光2M复用通道", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场—恒泰220kV汇集站220kV线路：每套保护装置均采用专用光纤+光2M复用通道。（P4003）"},
    # —— A2f：4.3.6 储能系统（不涉及，不抽）＋4.3.7 消防工程（P4027–P4072 共 33 行；
    #     P4044/P4046/P4048/P4052/P4059 为 A./B./a./b./c./D. 引导标题不抽）——
    {"id": "sp-658", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防设计遵循法规与方针", "required_value": "遵循《中华人民共和国消防法》及国家和行业现行规程规范，贯彻预防为主、防消结合方针，以自救为主、外援为辅为指导思想，防止和减少火灾危害，保障人身和财产安全", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场和升压站的消防设计应遵循《中华人民共和国消防法》及国家和行业的现行规程规范，贯彻“预防为主，防消结合”方针，以“自救为主，外援为辅”为指导思想，防止和减少火灾危害，保障人身和财产安全。（P4028）"},
    {"id": "sp-659", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防给水系统与灭火装置设置", "required_value": "生活舱占地面积小于300m2，按规定可不设置消防给水系统；根据消防对象具体情况设置火灾报警装置和专用灭火装置，合理配置灭火器；风电机组没有配置自动灭火系统时应配置灭火器材；站内变压器采用排油注氮固定灭火装置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站内生活舱占地面积小于300m2，按规定可不设置消防给水系统。本工程根据消防对象具体情况设置火灾报警装置和专用灭火装置，合理配置灭火器。风电机组没有配置自动灭火系统时应配置灭火器材，站内变压器采用排油注氮固定灭火装置。（P4029）"},
    {"id": "sp-660", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防新技术新材料应用", "required_value": "在满足安全适用、技术先进、经济合理条件下，积极采用新技术、新工艺、新材料和新设备，并符合国家现行有关强制性标准规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "针对工程具体情况，在满足安全适用、技术先进、经济合理的条件下，积极采用新技术、新工艺、新材料和新设备，并应符合国家现行有关强制性标准的规定。（P4030）"},
    {"id": "sp-661", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防设备配置标准符合", "required_value": "消防设备配置应满足GB50229、GB50140及DL5027中的有关规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站消防设备的配置应满足《火力发电厂和变电站设计防火标准》GB50229、《建筑灭火器配置设计规范》GB50140 及《电力设备典型消防规程》DL5027 中的有关规定。（P4031）"},
    {"id": "sp-662", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防体系与设施配置原则", "required_value": "应设立完整的消防体系，有效预防并及时扑灭以电气和油品为主的各种初期火灾，保障人员安全疏散和安全生产；消防设施包括消防供水、消防供电、应急照明、自动报警、防火排烟系统等；消防设施配置按站内同一时间可能发生的火灾次数为1次考虑", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站应设立完整的消防体系，有效预防并及时扑灭以电气和油品为主的各种初期火灾，保障人员的安全疏散和安全生产。消防设施包括消防供水、消防供电、应急照明、自动报警、防火排烟系统等。消防设施配置按站内同一时间可能发生的火灾次数为1 次考虑。（P4033）"},
    {"id": "sp-663", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防总体布置安全距离", "required_value": "总体布置应符合GB50229对建构筑物安全距离的规定；电气设备选型应考虑防火要求、布置满足消防要求；电力电缆选型与敷设应考虑防火阻燃要求；建筑防火分区、防火隔断、防火间距、安全疏散、消防通道的设置应符合现行国家标准有关规定，并根据工程实际考虑消防车辆、设备进出和使用的便利性、人员疏散的快速性和安全性", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站总体布置应符合《火力发电厂和变电站设计防火标准》GB50229 中对建（构）筑物安全距离的规定。电气设备选型应考虑防火要求，布置上应满足消防要求。电力电缆选型与敷设应考虑防火阻燃要求。建筑防火分区、防火隔断、防火间距、安全疏散、消防通道的设置应符合现行国家标准的有关规定，并根据工程实际考虑消防车辆、设备进出和使用的便利性、人员疏散的快速性和安全性。（P4034）"},
    {"id": "sp-664", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "综合消防技术措施", "required_value": "采用综合消防技术措施，从防火、监测、报警、控制、灭火、排烟、救生等各方面入手，力争减少火灾发生可能，一旦发生也能在短时间内扑灭，使火灾损失减少到最低程度，同时确保火灾时人员安全疏散", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程消防总体设计采用综合消防技术措施，根据消防系统的功能要求，从防火、监测、报警、控制、灭火、排烟、救生等各方面入手，力争减少火灾发生的可能，一旦发生也能在短时间内予以扑灭，使火灾损失减少到最低程度。同时 确保火灾时人员的安全疏散。（P4035）"},
    {"id": "sp-665", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "升压站总体布置防火措施", "required_value": "220kV升压站总体布置采用35kV预制舱、35kV户外配电装置等电气设备布置方案，35kV集中配电室和电气设备集中布置于一个站区内；各建筑物间安全距离均满足防火规范要求；带油主变压器单独布置在室外，配有独立总事故油池，并与户外220kV配电装置保持安全距离", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "220kV 升压站总体布置采用35kV 预制舱、35kV 户外配电装置等电气设备等布置方案，35kV 集中配电室和电气设备集中布置与一个站区内。各建筑物间的安全距离均满足防火规范要求；带油主变压器单独布置在室外，配有独立总事故油池，并与户外220kV 配电装置保持安全距离。（P4036）"},
    {"id": "sp-666", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电气设备防火与消防道路", "required_value": "电气设备选型考虑防火要求；站内通道净宽≥1.2m、楼道净宽≥1.1m、坡度≤45°；场地内设置消防道路，宽4.5m、转弯半径≥9.0m、呈环形布置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电气设备选型考虑防火要求。站内通道净宽≥1.2m，楼道净宽≥1.1m，坡度≤45°，场地内设置消防道路，宽4.5m，道路转弯半径≥9.0m，道路呈环形布置。（P4037）"},
    {"id": "sp-667", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "主变灭火器与消防设施配置", "required_value": "主变配备1具50kg推车式干粉灭火器及2具5kg手提式干粉灭火器，就近布置在主变旁，露天设置的灭火器加设遮阳棚；主变及室外含油带电设备附近应设置灭火砂箱（容积1m³）；还应配置消防铲、消防斧、消防铅桶等作为变电站公用消防设施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "主变配备1具50kg的推车式干粉灭火器及2具5kg的手提式干粉灭火器，就近布置在主变旁，露天设置的灭火器加设遮阳棚。同时主变以及室外含油带电设备附近应设置灭火砂箱，砂箱容积 1m³。此外，还应配置一定数量的消防铲、消防斧、消防铅桶等作为变电站公用消防设施。（P4038）"},
    {"id": "sp-668", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电气房间灭火器配置", "required_value": "电气房间各设置4具MF/ABC5手提式磷酸胺盐干粉灭火器；通信机房、低压配电室各设置MF/ABC4手提式磷酸胺盐干粉灭火器；每层走道组合式消防柜内设置2具MF/ABC4手提式磷酸胺盐干粉灭火器", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电气房间各设置 4 具 MF/ABC5 手提式磷酸胺盐干粉灭火器，通信机房、低压配电室各设置具 MF/ABC4手提式磷酸胺盐干粉灭火器，并在每层走道的组合式消防柜内设置 2 具 MF/ABC4 手提式磷酸胺盐干粉灭火器。（P4039）"},
    {"id": "sp-669", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "风电机组火灾自动探测报警系统", "required_value": "根据NB31089、DL5027和CECS391要求，风电机组机舱及机舱平台底板下部、塔架及竖向电缆桥架、塔架底部设备层、各类电气柜应设置火灾自动探测报警系统；报警信号应与风电机组中心控制系统相连并传输至升压站监控系统（探测点硬接线接入风机PLC，经光纤环网上传）", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据《风电场设计防火规范》NB31089、《电力设备典型消防规程》DL5027和《风力发电机组消防系统技术规程》CECS391 的相关要求，风电机组的机舱及机舱平台底板下部、塔架及竖向电缆桥架、塔架底部设备层、各类电气柜应设置火灾自动探测报警系统。火灾自动探测报警系统报警信号应与风电机组中心控制系统相连，传输至风电场升压站监控系统，即火灾报警探测点通过硬接线形式接入风机 PLC，通过风机光纤环网上传至升压站风机监控系统。（P4041）"},
    {"id": "sp-670", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "风电机组自动灭火装置配置", "required_value": "根据NB31089、DL5027和CECS391要求，风电机组机舱及机舱平台底板下部、轮毂、塔架底部设备层、各类电气柜配置自动灭火装置；布置在塔架内的机组变压器应配置自动灭火装置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据《风电场设计防火规范》NB31089、《电力设备典型消防规程》DL5027和《风力发电机组消防系统技术规程》CECS391 的相关要求，风电机组的机舱及机舱平台底板下部、轮毂、塔架底部设备层、各类电气柜配置自动灭火装置。布置在塔架内的机组变压器应配置自动灭火装置。（P4042）"},
    {"id": "sp-671", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻燃电缆场所-联动系统回路", "required_value": "应急照明、火灾自动报警、自动灭火装置、防排烟设施、消防水泵等联动系统", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "应急照明、火灾自动报警、自动灭火装置、防排烟设施、消防水泵等联动系统；（P4045）"},
    {"id": "sp-672", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电缆通道分层敷设与耐火隔板", "required_value": "电缆通道及电缆桥架上敷设的动力电缆、控制电缆、通信电缆及光缆等均应分类、分层排列敷设；动力电缆上下层（电缆竖井内动力电缆即左右列）之间应装设耐火隔板，耐火极限不低于1h", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "a.电缆通（沟、隧）道中及在电缆桥架上敷设的动力电缆、控制电缆、通信电缆 及光缆等均应分类、分层排列敷设。动力电缆的上下层（对于电缆竖井内的动力电缆即为左右列）之间，应装设耐火隔板，其耐火极限不应低于1h。（P4047）"},
    {"id": "sp-673", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电缆孔洞封堵（楼板墙体夹层）", "required_value": "电缆穿越楼板、墙体、电缆室（夹层）的孔洞应用耐火极限不低于1h的不燃材料封堵；封堵层应能承受巡检人员荷载；活动人孔可采用承重型防火隔板制作", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电缆穿越楼板、墙体、电缆室（夹层）的孔洞。封堵层应能承受巡检人员的荷载。活动人孔可采用承重型防火隔板制作。（P4049）"},
    {"id": "sp-674", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电缆引接孔洞防火", "required_value": "电缆引接至所有的屏、柜、箱等中的电缆孔洞", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电缆引接至所有的屏、柜、箱等中的电缆孔洞。（P4050）"},
    {"id": "sp-675", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电缆保护管两端防火", "required_value": "电缆保护管的两端", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电缆保护管的两端。（P4051）"},
    {"id": "sp-676", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻火墙设置部位-主沟道分支引接处", "required_value": "主沟道的分支电缆沟引接处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "主沟道的分支电缆沟引接处。（P4053）"},
    {"id": "sp-677", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻火墙设置部位-室外进入室内", "required_value": "室外进入室内电缆沟道处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "室外进入室内电缆沟道处。（P4054）"},
    {"id": "sp-678", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻火墙设置部位-不同电压交界处", "required_value": "不同电压配电装置交界处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "不同电压配电装置交界处。（P4055）"},
    {"id": "sp-679", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻火墙设置部位-长距离通道每隔100m", "required_value": "长距离电缆通道中每相隔约100m处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "长距离电缆通道中每相隔约100m处。（P4056）"},
    {"id": "sp-680", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻火墙设置部位-电缆沟道与围墙交叉处", "required_value": "电缆沟道与围墙的交叉处", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": " 电缆沟道与围墙的交叉处。（P4057）"},
    {"id": "sp-681", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "阻燃电缆防火保护措施豁免", "required_value": "阻燃或耐火电缆可不设层间防火隔板、不刷防火涂料；当其敷设在电缆室（夹层）中、电缆通道中时，可不采取防火保护措施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "C.阻燃或耐火电缆可不设层间防火隔板、不刷防火涂料。当其敷设在电缆室（夹层）中、电缆通（沟、隧）道中时，可不采取防火保护措施。（P4058）"},
    {"id": "sp-682", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "非阻燃电缆明敷-易受外因波及场所防护", "required_value": "在易受外因波及而着火的场所，宜对该范围内的电缆实施阻燃防护；对重要电缆回路可在适当部位设置阻火段以阻止延燃；电缆数量较多时也可采用阻燃、耐火槽盒或阻火包等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "a.在易受外因波及而着火的场所，宜对该范围内的电缆实施阻燃防护；对重要电缆回路，可在适当部位设置阻火段以阻止延燃。当电缆数量较多时，也可采用阻燃、耐火槽盒或阻火包等。（P4060）"},
    {"id": "sp-683", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "非阻燃电缆明敷-接头两侧防火包带", "required_value": "在接头两侧电缆各约3m区段和该范围内邻近并行敷设的其他电缆上，宜采用防火包带阻止延燃", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "b.在接头两侧电缆各约3m区段和该范围内邻近并行敷设的其他电缆上，宜采用防火包带阻止延燃。（P4061）"},
    {"id": "sp-684", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电气房间灭火器与烟感探测配置", "required_value": "主要电气房间（一次舱、二次舱、SVG室等）根据火灾危险性等级配置一定数量手提式灭火器，同时配备烟感探测装置及手动报警器；各房间所有通往室外的电缆孔洞、电气设备穿墙后留下的孔洞均采用防火材料封堵", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站主要电气房间有一次舱、二次舱、SVG室等，根据其火灾危险性等级，配置一定数量的手提式灭火器，同时配备烟感探测装置及手动报警器。各房间所有通往室外的电缆孔洞、电气设备穿墙后留下的孔洞均采用防火材料封堵。（P4063）"},
    {"id": "sp-685", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "环形消防道路", "required_value": "所内设有环形道路，主路宽4.5m，其他道路宽4.0m，内缘回转半径7m，消防车可顺利通至各建筑物及构筑物附近", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "所内设有环形道路，主路宽4.5m，其他道路宽为4.0m，内缘回转半径为7m，消防车可顺利通至各建筑物及构筑物附近，便于消防。（P4065）"},
    {"id": "sp-686", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "建筑物构筑物间距防火", "required_value": "各建筑物、构筑物之间按照火灾危险性类别及最低耐火等级的划分，其间距均符合防火规程的规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "各建筑物，构筑物之间，按照火灾危险性类别及最低耐火等级的划分，其间距均符合防火规程的规定。（P4066）"},
    {"id": "sp-687", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "电缆孔洞封堵与防火分隔", "required_value": "电缆穿越楼板、隔墙孔洞和进出开关柜、配电盘孔洞均应采用防火堵料封堵；动力电缆与控制电缆分层敷设，动力电缆上下电缆层之间装设耐火隔板（耐火极限不低于1.5h）；动力和控制电缆廊道每60m、电缆沟每200m、电缆竖井每2～3层设防火分隔（不低于3h）；电缆道防火分区处设防火分隔板（不低于3h），分隔板两侧隔1m电缆区段设防止串火措施；电缆与电缆、管道、道路、构筑物等之间距离满足GB50217第5.3.5条要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电缆穿越楼板、隔墙的孔洞和进出开关柜、配电盘等的孔洞均应采用防火堵料进行封堵。动力电缆与控制电缆分层敷设，动力电缆上下电缆层之间装设耐火隔板，其耐火极限不低于1.5h。动力和控制电缆廊道每60m、电缆沟每200m、电缆竖井每2～3层设防火分隔，其耐火极限不低于3h。在电缆道防火分区 处均设防火分隔板，其耐火极限不低于3h。在防火分隔板两侧隔1m的电缆区段上，设防止串火的措施。电缆与电缆、管道、道路、构筑物等之间的距离满足《电力工程电缆设计规范》GB50217第5.3.5条的要求。（P4067）"},
    {"id": "sp-688", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "消防电源双回路供电", "required_value": "消防电源采用独立的双回路供电，一回路由系统供电，另一回路由当地地区外来电源供电（施工电源保留）；两路电源可自动切换，满足消防电源供电要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "消防电源采用独立的双回路供电，一回路是由系统供电；另一回路由当地地区外来电源供电（施工电源保留）。两路电源可以自动切换，满足消防电源供电要求。（P4068）"},
    {"id": "sp-689", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "灭火器配置与选型", "required_value": "根据容量大小及重要性配备适当数量的手提式及推车式化学灭火器用于电气设备及建筑物灭火；灭火器应选择灭火效能高、使用方便、能长期存放不失效、喷射距离远的品种", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站应根据其容量大小及重要性，配备适当数量的手提式及推车式化学灭火器用于电气设备及建筑物的灭火。灭火器应选择灭火效能高、使用方便、能长期存放不失效、喷射距离远的品种。（P4070）"},
    {"id": "sp-690", "clause": "第五章4.3.7消防工程", "page": "n/a-无分页",
     "requirement": "火灾自动报警系统配置", "required_value": "根据GB50116-2013设计；选用一套集中报警系统，包含火警集中报警控制器、火灾探测器、声光报警器、手动报警按钮、消防通讯设备、消防联动控制设备等；探测总线采用二总线，探测报警和联动控制共用一条总线；集中报警控制器能显示火灾报警区域和探测区域，通过联动控制设备对相关设备进行联动控制", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程火灾自动报警系统根据《火灾自动报警系统设计规范》GB50116-2013的要求设计。选用一套集中报警系统，包含火警集中报警控制器、火灾探测器、声光报警器、手动报警按钮、消防通讯设备、消防联动控制设备等。火灾自动报警系统探测总线采用二总线，探测报警和联动控制共用一条总线；火灾集中报警 控制器能显示火灾报警区域和探测区域，通过联动控制设备可对相关设备进行联动控制。（P4072）"},
    # —— A2g：4.4 土建技术标准（P4073–P4263；P4097 对外交通叙述段不抽）——
    {"id": "sp-691", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "风机装机参数与塔筒型式", "required_value": "16台×6.25MW，总装机100MW，叶轮直径220m，轮毂高度160m，塔筒为混合塔筒", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "风电场工程拟安装16台单机容量为6.25MW的风力发电机组，总装机容量100MW，叶轮直径220m，轮毂高度160m的风力发电机组，塔筒为混合塔筒。（P4075）"},
    {"id": "sp-692", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "风电场工程规模划分", "required_value": "按NB/T10101-2018第4.0.1条，按照装机容量和变电站电压等级划分，本风电场工程规模为大型", "unit": "",
     "tolerance": "", "no_negative_allowed": False,
     "raw_text": "根据《风电场工程等级划分及设计安全标准》（NB/T10101-2018）第4.0.1条规定，按照装机容量和变电站电压等级划分，本风电场工程规模为大型。（P4076）"},
    {"id": "sp-693", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "塔架地基基础设计级别与结构安全等级", "required_value": "按NB/T10101-2018第4.0.2、5.0.3条，6.25MW机组塔架地基基础设计级别为甲级，结构安全等级为一级", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据 NB/T10101-2018 第4.0.2、5.0.3条规定，本工程6.25MW机组塔架地基基础设计级别为甲级，结构安全等级为一级。（P4077）"},
    {"id": "sp-694", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "风电机组基础结构安全等级", "required_value": "按NB/T 10311-2019第3.1.8条，风电机组基础结构安全等级为一级", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据 《陆上风电场工程风电机组基础设计规范》NB/T 10311-2019第3.1.8条规定，本工程风电机组基础结构安全等级为一级。（P4078）"},
    {"id": "sp-695", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "开关站建筑物级别", "required_value": "按NB/T10101-2018第4.0.3条，220kV开关站建筑物级别为2级", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据 NB/T10101-2018 第4.0.3条规定，本工程220kV开关站建筑物级别为2级。（P4079）"},
    {"id": "sp-696", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "建筑物抗震等级", "required_value": "按GB50011-2010表6.1.2，建筑物抗震等级为三级", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据《建筑抗震设计规范（2016年版）》GB50011-2010表6.1.2，建筑物抗震等级为三级。（P4080）"},
    {"id": "sp-697", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "建筑物结构安全等级", "required_value": "按NB/T10101-2018第5.0.2条，建筑物结构安全等级为二级", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据 NB/T10101-2018 第5.0.2条规定，本工程建筑物结构安全等级为二级。（P4081）"},
    {"id": "sp-698", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "风机基础初步方案（承台三节与混凝土）", "required_value": "承台总厚度5.1m，分三节（下节直径20.0m高0.9m圆柱体；中节底部直径20.0m上部直径11.0m高2.1m圆锥台；上节外径11.0m高0.5m圆柱体，内部中空，上部半径2.5m高3.5m空腔、下部半径4.7m高1.1m空腔），单个风机承台混凝土方量760m³；采用Ca40混凝土，抗渗等级P6，桩采用预制管桩", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "经计算，本阶段风机基础初步方案为：承台总厚度为5.1m，共分为三节：下节为直径20.0m、高0.9m的圆柱体，中节为底部直径20.0m、上部直径11.0m、高2.1m的圆锥台；上节为外径11.0m、高0.5米的圆柱体，内部中空，上部为半径2.5m、高3.5m的圆柱体空腔，下面为半径4.7m、高1.1m的圆柱体空腔，此方案单个风机承台混凝土方量为760m³。风机基础采用Ca40混凝土，抗渗等级为P6，桩采用预制管桩。（P4082）"},
    {"id": "sp-699", "clause": "第五章4.4.1风机基础", "page": "n/a-无分页",
     "requirement": "特殊机位点风机基础排水措施", "required_value": "对特殊机位点风机基础采取可靠的排水措施，防止场地及周边雨水对基础产生不利影响", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "对特殊机位点风机基础采取可靠的排水措施，防止场地及周边雨水对基础产生不利影响。（P4083）"},
    {"id": "sp-700", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-平纵面指标", "required_value": "平纵面指标尽量满足相关规范要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（1）平纵面指标尽量满足相关规范要求；（P4087）"},
    {"id": "sp-701", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-行车安全与路基稳定", "required_value": "保证行车安全性，保证路基稳定性", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（2）保证行车安全性，保证路基稳定性；（P4088）"},
    {"id": "sp-702", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-大型构件运输", "required_value": "满足本项目大型构件运输要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（3）满足本项目大型构件运输要求；（P4089）"},
    {"id": "sp-703", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-少占农田避免拆迁", "required_value": "尽量减少占用农田、避免拆迁", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（4）尽量减少占用农田、避免拆迁；（P4090）"},
    {"id": "sp-704", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-减少林地破坏", "required_value": "尽量减少对林地的破坏", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（5）尽量减少对林地的破坏；（P4091）"},
    {"id": "sp-705", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计原则-保护生态环境", "required_value": "保护生态环境", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "（6）保护生态环境。（P4092）"},
    {"id": "sp-706", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路设计范围", "required_value": "本期风电场道路设计范围为场内道路部分", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本期风电场道路设计范围为场内道路部分。（P4094）"},
    {"id": "sp-707", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "场内道路标准与规模", "required_value": "场内道路标准参照四级道路和风机厂商提供的风机运输道路设计资料进行修建规划；检修道路共30.3公里（场内新建5.3公里、改建25公里），场内道路采用碎石路面", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本风电场场区地形起伏较小，场内道路多为乡村道路与田间小路，风电机组设备场内运输较为困难，各风电机位之间需按相关标准修建道路以满足设备运输及施工期大型车辆的通行。场内道路标准参照四级道路和风电机组厂商提供的风机运输道路的设计资料进行修建规划风电场的场内道路路径，检修道路共30.3公里，其中场内新建道路5.3公里，改建道路25公里，场内道路采用碎石路面。（P4099）"},
    {"id": "sp-708", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路平面设计指标", "required_value": "在满足JTGD20-2017基础上充分考虑平纵横组合设计；圆曲线最小半径35m；曲线段路基超高绕曲线内侧行车道边缘旋转、最大超高2%；平曲线加宽R≥35m按公路三类加宽值；曲线外侧须沿开挖至路肩高程避免扫尾；曲线半径R<80m时道路外侧8m内不得有不可移动障碍物", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程在满足《公路路线设计规范》（JTGD20-2017）的基础上，充分考虑了路线平、纵、横三方面的组合设计。道路平面线型由圆曲线和直线组成，圆曲线最小半径采用35m。道路曲线段路基超高方式为绕曲线内侧行车道边缘旋转，最大超高为 2%；平曲线加宽：R≥35m，按公路三类加宽值；曲线外侧须沿开挖至路肩高程以避免扫尾。为保证超长件叶片及塔筒运输安全，曲线半径 R<80m 时，道路外侧8m内不得有不可移动的障碍物。（P4101）"},
    {"id": "sp-709", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "公路等级", "required_value": "参照四级公路标准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "公路等级：参照四级公路标准；（P4103）"},
    {"id": "sp-710", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "计算行车速度", "required_value": "15km/h", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "计算行车速度：15km/h；（P4104）"},
    {"id": "sp-711", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路基路面宽度", "required_value": "6m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "路基路面宽度：6m；（P4105）"},
    {"id": "sp-712", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "平曲线极限最小半径", "required_value": "35m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "平曲线极限最小半径：35m；（P4106）"},
    {"id": "sp-713", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "竖曲线最小半径极限值", "required_value": "550m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "竖曲线最小半径极限值550m；（P4107）"},
    {"id": "sp-714", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路纵坡", "required_value": "干线最大纵坡12%，支线最大纵坡15%", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "道路纵坡：干线最大纵坡为 12%，支线最大纵坡为 15%；（P4108）"},
    {"id": "sp-715", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路拱横坡", "required_value": "2.0%", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "路拱横坡：2.0％（P4109）"},
    {"id": "sp-716", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路横断面设计", "required_value": "新建路基横断面设计为整体式断面，路面横坡2%、土路肩横坡3%；路基宽6m、行车道宽5m、土路肩每侧宽0.5m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据《公路路线设计规范》（JTGD20-2017）要求以及结合沿线实际地形、地质、水文条件等情况，新建路基横断面设计为整体式断面，路面横坡 2%，土路肩横坡 3%。路基宽 6m，行车道宽5m，土路肩每侧宽0.5m。（P4111）"},
    {"id": "sp-717", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路基标准与边坡", "required_value": "全线路基采用四级公路标准，路线中断面设计高程指公路中线路面高程；填方路堤边坡1:1.5，挖方路堑边坡1:0.75~1:1", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "(1) 全线路基采用四级公路标准，路线中断面设计高程指公路中线路面高程。填方路堤边坡1：1.5，挖方路堑边坡为1：0.75~1：1。（P4114）"},
    {"id": "sp-718", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路基填料选择与CBR要求", "required_value": "填方路基应优先选用级配较好的砾类土、砂类土等粗粒土作为填料，填料最大粒径应小于150mm；泥炭、淤泥、冻土、强膨胀土、有机质土等不得直接用于填筑路基；细粒土填筑时路堤填料最大强度（CBR）：1.5m以下≥2%、0.8~1.5m≥3%、0.3~0.8m≥3%、0~0.3m≥5%", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "(2) 填料选择：填方路基应优先选用级配较好的砾类土、砂类土等粗粒土作为填料，填料最大粒径应小于150mm。泥炭、淤泥、冻土、强膨胀土、有机质土等不得直接用于填筑路基。当采用细粒土填筑时，路堤填料的最大强度要求为：1.5m以下 CBR(%)值≥2，0.8~1.5m CBR(%)值≥3, 0.3~0.8m以下 CBR(%)值≥3，0~0.3m CBR(%)值≥5。（P4115）"},
    {"id": "sp-719", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路基压实度要求", "required_value": "路基填土须分层填筑，每层压实厚度不得超过30cm；路堤1.5m以下压实度≥90%，控方路床0~0.3m≥94%", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "(3) 压实度要求：路基填土须分层填筑，每层压实厚度不得超过30cm。压实度要求为：路堤：1.5m以下，≥90%，控方路床：0~0.3m，≥94%。（P4116）"},
    {"id": "sp-720", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路面结构与换填", "required_value": "路面采用碎石路面；新建道路及原有道路扩建段路面下换填0.8m厚碎石，道路表面铺5cm厚级配耐磨层", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "路面采用碎石路面。本工程所处天津地区属于降雨较多地区，且路面耕土层较厚，下雨天道路泥泞，不利于风机运输，因此考虑新建道路及原有道路扩建段路面下换填0.8m厚碎石，道路表面铺5cm厚级配耐磨层。（P4118）"},
    {"id": "sp-721", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路平面度", "required_value": "道路的平面度满足在长度35m范围内，路面的最高处与最低处高度差小于150mm", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "道路的平面度满足在长度35 m范围内，路面的最高处与最低处高度差小于150 mm。（P4119）"},
    {"id": "sp-722", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路加宽-倒运车运输", "required_value": "叶片机舱轮毂使用倒运车运输情况下，道路内弯和外弯加宽量均由塔筒车决定；本工程最小转弯半径为50m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "对于同一通行道路，叶片机舱轮毂使用倒运车运输情况下，道路内弯和外弯加宽量均由塔筒车决定，本工程最小转弯半径为50m.（P4121）"},
    {"id": "sp-723", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路加宽-平板车运输", "required_value": "叶片使用长途抽拉平板车运输情况下，道路内弯和外弯加宽量均由叶片车决定；采用外弯通行时，弯道外侧32米无障碍", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "对于同一通行道路，叶片使用长途抽拉平板车运输情况下，道路内弯和外弯加宽量均由叶片车决定；采用外弯通行时，弯道外侧32米无障碍。（P4122）"},
    {"id": "sp-724", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "最大纵坡坡长表", "required_value": "纵坡坡度4%→最大坡长1200m、5%→1000m、6%→800m、7%→600m、8%→400m、9%→300m、10%→200m、11%→150m、12~16%→100m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "最大坡长（m）\t1200\t1000\t800\t600\t400\t300\t200\t150\t100（T37R2）"},
    {"id": "sp-725", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "最小坡长与缓和坡段", "required_value": "最小坡长60m；连续上坡（或下坡）时，应在不大于上表所规定的纵坡长度范围内设置缓和坡段；缓和坡段纵坡不大于3%，其长度应符合纵坡长度规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "其中最小坡长为60m，连续上坡（或下坡）时，应在不大于上表所规定的纵坡长度范围内设置缓和坡段。缓和坡段的纵坡应不大于3%，其长度应符合纵坡长度的规定。（P4124）"},
    {"id": "sp-726", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "桥涵设置与承载要求", "required_value": "一般水渠可采用管涵保证过水能力不受影响，一般采用Ф0.5~1m、壁厚70mm圆管涵，水量偏大处可采用双管或三管并排设置；大跨度桥梁需评估承载能力并采取加固措施，本工程风场道路所经桥梁需满足汽20-挂100要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程所处地区水系发达，风场道路穿越水渠及桥梁较多，对于一般水渠可采用管涵保证过水能力不受影响，一般采用Ф0.5~1m，壁厚70mm圆管涵，考虑过水能力和实际需要等问题，可在水量偏大处采用双管或者三管并排设置，以达到排水泄洪的目的。 对于大跨度桥梁，需评估桥梁承载能力，根据实际情况采取加固措施，本工程风场道路所经桥梁需满足汽20-挂100要求。（P4126）"},
    {"id": "sp-727", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "沿线筑路材料与水电供应", "required_value": "道路施工需要的建筑材料可采取就近原则进行采购；施工用水用电可由附近村镇接引", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "道路施工需要的建筑材料可采取就近原则进行采购。施工用水用电可由附近村镇接引。（P4128）"},
    {"id": "sp-728", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "道路施工环境与文物保护", "required_value": "道路施工时严格执行环境和自然文物的保护，在选线时进行文物区避让，在施工时进行警示牌、围护等措施进行保护", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "道路施工时严格执行环境和自然文物的保护，在选线时进行文物区避让，在施工时进行警示牌，围护等措施进行保护。（P4130）"},
    {"id": "sp-729", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "排水沟与护坡", "required_value": "道路所处区域降雨量大，填方地段排水经路堤坡面就近排到自然水沟或路基低洼处；汇水位置冲刷路基坡脚处需设置涵洞", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "道路所处区域降雨量大，填方地段排水经路堤坡面就近排到自然水沟或路基低洼处。汇水位置冲刷路基坡脚处需设置涵洞。（P4132）"},
    {"id": "sp-730", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "路基施工前处理", "required_value": "路基施工前应将用地范围内杂草、垃圾、淤泥、积水、腐殖土清除，并压实后（压实度≥85%）才能分层填筑", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "1）路基施工前应将用地范围内杂草、垃圾、淤泥、积水、腐殖土清除，并压实后（压实度≥85%）才能分层填筑。（P4134）"},
    {"id": "sp-731", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "新旧路基台阶开挖", "required_value": "新旧路基结合处及地面坡度较陡时（坡度>1:5）应开挖宽度1m的台阶", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "2） 新旧路基结合处及地面坡度较陡时（坡度>1:5）应开挖宽度1m的台阶。（P4135）"},
    {"id": "sp-732", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "场内吊装平台设计", "required_value": "在每台风机周围整平出50m×70m的平台供安装使用；主吊区换填1m厚碎石以满足风机吊装要求；吊装平台其他区域铺设钢板（可重复利用）", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "根据风电场风机的布置方案，结合风电场场址区域内的地形地貌特征。在每台风机周围，整平出50m×70m的平台供安装使用。主吊区换填1m厚碎石，以满足风机吊装的要求。吊装平台其他区域铺设钢板（可重复利用）。（P4137）"},
    {"id": "sp-733", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "安全护栏形式与限界", "required_value": "安全护栏形式主要包括防撞墩、波形钢护栏、防撞墙（混凝土护栏）；安全护栏位于道路土路肩内，护栏的任何部分不得侵入道路建筑限界以内", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场道路安全护栏的形式主要包括防撞墩、波形钢护栏、防撞墙（混凝土护栏）。安全护栏位于道路土路肩内，护栏的任何部分不得侵入道路建筑限界以内。（P4141）"},
    {"id": "sp-734", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "安全护栏设置原则", "required_value": "路基宽度＜7m且满足任一条件时必须设置安全护栏：路堤高度≥6m且边坡坡度≥1:1.5的路段、道路纵坡≥12%且路堤边坡坡度≥1:1.5高度≥3m的路段、路侧有悬崖深谷深沟的路段、道路纵坡≥10%且路堤边坡坡度≥1:1.5的回头弯路段、路肩墙高度≥4m的路段", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "路基宽度＜7m，且满足以下任一条件时，必须设置安全护栏。路堤高度≥6m,且边坡坡度≥1:1.5 的路段。道路纵坡≥12%，且路堤边坡坡度≥1:1.5、高度≥3m 的路段。路侧有悬崖、深谷、深沟等的路段。道路纵坡≥10%时，且路堤边坡坡度≥1:1.5 的回头弯路段。（P4143）"},
    {"id": "sp-735", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "安全护栏反光涂料", "required_value": "安全护栏应涂刷反光型涂料", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "路肩墙高度≥4m 的路段。安全护栏应涂刷反光型涂料。（P4144）"},
    {"id": "sp-736", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "警示设施-安全桩功能", "required_value": "风电场道路交通安全警示设施一般使用安全桩；常规的安全桩仅具有警示及隔离功能，不具备可靠的防撞功能", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场道路交通安全警示设施一般使用安全桩。常规的安全桩仅具有警示及隔离功能，不具备可靠的防撞功能。（P4147）"},
    {"id": "sp-737", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "警示设施设置原则-悬崖深谷深沟", "required_value": "在道路线型条件良好、路侧高差在2m以内的悬崖、深谷、深沟路段可采用警示设施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "在道路线型条件良好，路侧高差在2m 以内的悬崖、深谷、深沟路段可采用警示设施。（P4149）"},
    {"id": "sp-738", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "警示设施设置原则-村庄景区隔离", "required_value": "当道路穿越村庄、景区或其他区域道路需要与周边环境进行隔离、警示时，可采用警示设施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "当道路穿越村庄、景区或其他区域道路需要与周边环境进行隔离、警示时，可采用警示设施。（P4150）"},
    {"id": "sp-739", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "安全桩构造与基础", "required_value": "安全桩从路面到护栏顶部的高度不低于100cm；安全桩基础应置于稳定地基上，当位于填土地基时地基土压实度不小于94%", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "安全桩从路面到护栏顶部的高度不低于100cm。安全桩基础应置于稳定地基上，当位于填土地基时，地基土压实度不小于94%。（P4152）"},
    {"id": "sp-740", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "安全桩土路肩保护层与反光", "required_value": "外侧土路肩保护层厚度不小于25cm、埋深不小于30cm；当外侧土路肩保护层厚度小于25cm时应采取一定的加强措施；安全桩应涂刷反光型涂料", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "外侧土路肩保护层厚度不小于25cm，埋深不小于30cm。当外侧土路肩保护层厚度小于25cm 时，应采取一定的加强措施。安全桩应涂刷反光型涂料。（P4153）"},
    {"id": "sp-741", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "交通标志符合GB5768", "required_value": "风电场道路交通标志的分类、形状、图案、颜色、文字、规格应符合现行《道路交通标志和标线》(GB 5768)的规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "风电场道路交通标志的分类、形状、图案、颜色、文字、规格，应符合现行《道路交通标志和标线》(GB 5768)的规定。（P4156）"},
    {"id": "sp-742", "clause": "第五章4.4.2道路及吊装平台设计", "page": "n/a-无分页",
     "requirement": "交通标志指示内容", "required_value": "交通标志除满足现行《道路交通标志和标线》(GB 5768)的规定外，还应包含线路风机位、风机支线等指示标志", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "b）交通标志除满足现行《道路交通标志和标线》(GB 5768)的规定外，还应包含线路风机位、风机支线等指示标志。（P4157）"},
    {"id": "sp-743", "clause": "第五章4.4.3升压站布置", "page": "n/a-无分页",
     "requirement": "升压站组成与设计标高", "required_value": "本期新建一座220kV升压站，包括综合楼、GIS、主变、SVG、小电阻成套接地装置、生产辅助用房、35kV预制舱等；升压站位于风电场区中部和村庄旁，交通方便；升压站场地设计标高取19.50m，升压站需填高以满足要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本期新建一座220kV升压站，包括综合楼、GIS、主变、SVG、小电阻成套接地装置、生产辅助用房、35kV预制舱等。升压站位于风电场区中部和村庄旁，交通方便。升压站场地设计标高取19.50m，升压站需填高以满足要求。（P4159）"},
    {"id": "sp-744", "clause": "第五章4.4.3升压站布置", "page": "n/a-无分页",
     "requirement": "升压站道路与分区布置", "required_value": "进站道路与南侧水泥路相连，站内设置环形道路，路面宽度4.5m、转弯半径9m；整体布置采用生产、生活分区布置方案（生活区南侧布置两层综合楼，出口位于站区北侧，综合楼西侧和南侧分别为单层生产辅助用房及污水处理装置等；生产区西部布置GIS、SVG，主变、出线构架等，配电室内放置开关柜）；生产区和生活区采用围栏隔离", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站进站道路与南侧水泥路相连，站内设置环形道路，道路路面宽度为4.5m，转弯半径为9m。升压站整体布置采用生产、生活分区布置方案，生活区南侧布置有一座两层的综合楼，综合楼出口位于站区北侧，综合楼西侧和南侧分别为一座单层的生产辅助用房以及污水处理装置等，生产区西部布置GIS、SVG，主变、出线构架等，配电室内放置开关柜。生产区和生活区采用围栏隔离。（P4160）"},
    {"id": "sp-745", "clause": "第五章4.4.4采暖通风", "page": "n/a-无分页",
     "requirement": "室内设计参数（预制舱）", "required_value": "预制舱内由厂家设计", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "预制舱内由厂家设计。（P4163）"},
    {"id": "sp-746", "clause": "第五章4.4.4采暖通风", "page": "n/a-无分页",
     "requirement": "采暖系统设计", "required_value": "本工程不涉及集中采暖系统，冬季对有人员停留的场所或工艺对室内温度有要求的场所，采用电暖器供热满足要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程不涉及集中采暖系统，冬季对有人员停留的场所或工艺对室内温度有要求的场所，采用电暖器供热满足要求。（P4165）"},
    {"id": "sp-747", "clause": "第五章4.4.4采暖通风", "page": "n/a-无分页",
     "requirement": "通风系统设计", "required_value": "配电室、二次设备室等采用自然进风、轴流风机机械排风的通风方式，通风换气量按每小时不小于12次设计考虑，并兼作夏季正常通风使用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "配电室、二次设备室等采用自然进风，轴流风机机械排风的通风方式，通风换气量按每小时不小于12次设计考虑，并兼作夏季正常通风使用。（P4167）"},
    {"id": "sp-748", "clause": "第五章4.4.4采暖通风", "page": "n/a-无分页",
     "requirement": "空调系统设计", "required_value": "配电室、二次设备室等采用风冷柜式降温机组调节室内温度，满足设备运行要求；综合楼内空调区域等均设置舒适性空调，空气调节装置采用风冷分体空调", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "配电室、二次设备室等采用风冷柜式降温机组调节室内温度，满足设备的运行要求。综合楼内空调区域等均设置舒适性空调，空气调节装置采用风冷分体空调。（P4169）"},
    {"id": "sp-749", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "给水系统水源与参数", "required_value": "升压站用水主要为站区生活用水及消防给水系统补水；消防水池补水时间不能超过48h；站内给水水源拟从附近冯飘村自来水管网接引，接引距离约1km，由自来水公司负责将1路DN100用水管道接至站区围墙外1m，水量不小于10m3/h，水压不小于0.20MPa，水质符合《生活饮用水卫生标准》", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站用水主要为站区生活用水及消防给水系统补水。考虑消防水池补水时间不能超过48h的要求，本工程站内给水水源拟从升压站附近的冯飘村自来水管网接引，接引距离约1km，由自来水公司负责将1路DN100的用水管道接至站区围墙外1m，水量不小于10m3/h，水压不小于0.20MPa，水质符合《生活饮用水卫生标准》。（P4172）"},
    {"id": "sp-750", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "排水系统体制", "required_value": "站区排水系统采用分流制，包括生活污水、生产废水及雨水系统", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "站区排水系统采用分流制。站区排水包括生活污水、生产废水及雨水系统。（P4174）"},
    {"id": "sp-751", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "生活污水处理", "required_value": "生活污水经管道收集后进入化粪池，经化粪池预处理后由第三方公司定期清运", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "生活污水经管道收集后进入化粪池，经化粪池预处理后，由第三方公司定期清运。（P4176）"},
    {"id": "sp-752", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "生产废水与事故油池", "required_value": "主变压器事故油池容量按照可储存其100%油量设计；事故油池有油水分离功能，分离出的水排入站区雨水系统，分离出的废油暂存在事故油池内不外排，事故处理后交由有资质单位处置", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程主变压器的事故油池容量按照可储存其100%油量设计。事故油池有油水分离功能，分离出的水排入站区雨水系统，分离出的废油暂存在事故油池内不外排，事故处理后交由有资质的单位进行处置。（P4178）"},
    {"id": "sp-753", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "雨水排水系统", "required_value": "雨水排水系统按储能站及升压站整体规模设计，站区雨水采用有组织排水、升压强排方式，根据场地竖向布置分区汇集，经雨水管道自流汇至一体化雨水泵站后升压排放至站外水体", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "雨水排水系统按储能站及升压站整体规模设计，站区雨水采用有组织排水、升压强排方式，站区内雨水根据场地竖向布置、分区汇集，经雨水管道自流汇至一体化雨水泵站后升压排放至站外水体。（P4180）"},
    {"id": "sp-754", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "雨水管道与检查井", "required_value": "雨水排水管道采用PE双壁波纹管，雨水检查井采用模块式预制混凝土圆形雨水检查井", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程雨水排水管道采用PE双壁波纹管，雨水检查井采用模块式预制混凝土圆形雨水检查井。（P4181）"},
    {"id": "sp-755", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "一体化雨水泵站", "required_value": "站内设1座一体化预制雨水泵站（埋地布置），筒体为玻璃钢材质，外形尺寸约φ3000×5000mm（直径×深），内设格栅、排水泵、液位计、配套阀门管件、控制柜等；2台排水泵参数暂定Q＝400m3/h、H＝10m、N＝22kW，根据泵站水位自动启停", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "站内设1座一体化预制雨水泵站，埋地布置。雨水泵站筒体为玻璃钢材质，外形尺寸约为φ3000×5000mm（直径×深），内设格栅、排水泵、液位计、配套阀门管件、控制柜等。雨水泵站内设置2台排水泵，参数暂定为：Q＝400m3/h，H＝10m，N＝22kW。排水泵根据雨水泵站内水位自动启停。（P4182）"},
    {"id": "sp-756", "clause": "第五章4.4.4给排水部分", "page": "n/a-无分页",
     "requirement": "雨水泵站出水管", "required_value": "雨水泵站出水排水管采用1根DN400的焊接钢管将雨水排至站外水体", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "雨水泵站出水排水管采用1根DN400的焊接钢管将雨水排至站外水体。（P4183）"},
    {"id": "sp-757", "clause": "第五章4.4.7集电线路土建", "page": "n/a-无分页",
     "requirement": "集电线路土建方式", "required_value": "集电线路拟采用电缆地埋加架空的方式，基础采用大开挖基础", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程集电线路拟采用电缆地埋加架空的方式。基础采用大开挖基础。（P4185）"},
    # —— 4.4.8 升压站土建（P4186–P4250；4.4.5/4.4.6 编号空缺、两个 4.4.4 重号，
    #     原文编号异常均照录）——
    {"id": "sp-758", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "综合楼结构与装修", "required_value": "外墙砌体围护、外刷外墙乳胶漆；窗双层玻璃铝合金窗，门钢质门/钢质防火门/木质门；二层建筑轴线尺寸34.3m×15.7m，零米层布置办公室/餐厅/厨房/卫生间/监控室/蓄电池室，二层布置休息室/活动室/办公室/会议室/资料室", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站综合楼外墙采用砌体围护，外刷外墙乳胶漆。窗采用双层玻璃铝合金窗，门为钢质门、钢质防火门、木质门。综合楼为二层建筑，轴线尺寸为34.3m×15.7m，零米层布置办公室、餐厅、厨房、卫生间、监控室、蓄电池室等，二层布置休息室、活动室、办公室、会议室、资料室。（P4188）"},
    {"id": "sp-759", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "综合楼屋面防水", "required_value": "屋面防水等级Ⅰ级、二道防水设防；现浇钢筋混凝土屋面板带保温层，防水层采用防水卷材二道", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "综合楼屋面防水等级为Ⅰ级，二道防水设防。屋面采用现浇钢筋混凝土屋面板带保温层，防水层采用防水卷材二道。（P4189）"},
    {"id": "sp-760", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "生产辅助用房结构", "required_value": "生产辅助用房单层钢筋混凝土结构，轴线尺寸25.5m×7.1m，布置工具室、备件间、水泵房等", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "生产辅助用房为单层钢筋混凝土结构，轴线尺寸为25.5mx7.1m，主要布置有工具室、备件间、水泵房等。（P4190）"},
    {"id": "sp-761", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "建筑物立面色彩", "required_value": "立面色彩以示例发包人标志色为主导（主墙面白色、檐口蓝灰色、墙脚浅灰色）；附属建筑设计力求和谐统一、符合集团形象定位；整合使用功能减少建筑物数量和体积以降低用地及建造成本", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站内建筑物的立面色彩采用示例发包人标志色为主导：主墙面为白色，檐口为蓝灰色，墙脚为浅灰色，凸显标志性。对附属建筑物的设计力求能够和谐统一，符合集团对电厂的形象定位。对各种使用功能进行整合，减少建筑物数量和体积，从而降低建筑用地及建造使用成本。附属建筑的室内外装修，根据不同使用功能的特性，注重实用。（P4191）"},
    {"id": "sp-762", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "实体围墙", "required_value": "升压站采用实体围墙（砌体围墙），围墙实体高度2.3米，防护网高度0.5m", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站采用实体围墙，围墙采用砌体围墙，围墙实体高度为2.3米，防护网高度为0.5m（P4192）"},
    {"id": "sp-763", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "地面楼面材料标准", "required_value": "材料品种、规格和质量应符合设计要求和国家现行标准规定；天然石材必须符合JC518《天然石材产品放射防护分类控制标准》规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "地面与楼面工程所用材料的品种、规格和质量应符合设计要求和国家现行标准的规定。地面采用的天然石材必须符合国家现行行业标准《天然石材产品放射防护分类控制标准》JC518的规定。（P4194）"},
    {"id": "sp-764", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "材料采购与样板确认", "required_value": "材料应是名牌产品，品种、规格、外观和尺寸须经监理和发包人批准并提供样板确认后方可采购；进场材料应具有相应检测报告", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "本工程的材料应是名牌产品，产品的品种、规格、外观和尺寸须经过监理和发包人的批准，并提供样板给监理和发包人确认后方可采购。进场的材料应具有相应的检测报告。（P4195）"},
    {"id": "sp-765", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "地面楼面施工队伍与方案", "required_value": "施工队伍应具备相应资质和类似工程施工经验，人员应有相应岗位资格证书；承包人应编制施工组织设计并经监理和发包人审查批准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承担地面与楼面工程施工的队伍应具备相应的资质和类似工程的施工经验。承担地面与楼面工程施工的人员应有相应岗位的资格证书。承包人应编制施工组织设计并应经过监理和发包人的审查批准。（P4196）"},
    {"id": "sp-766", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "地面楼面施工质量", "required_value": "施工质量应符合设计要求、DL/T5210.1-2021、GB50300和国家现行有关规范规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "地面与楼面工程的施工质量应符合设计要求、《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和国家现行有关规范的规定。（P4197）"},
    {"id": "sp-767", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "施工环境保护", "required_value": "应遵守环境保护法律法规，采取有效措施控制施工现场粉尘、废气、废弃物、噪声、振动等对周围环境的污染和危害", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应遵守有关环境保护的法律法规，并应采取有效措施控制施工现场的各种粉尘、废气、废弃物、噪声、振动等对周围环境造成的污染和危害。（P4198）"},
    {"id": "sp-768", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "半成品成品保护", "required_value": "施工过程中应做好半成品成品的保护，防止污染和损坏", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人在施工过程中应做好半成品成品的保护，防止污染和损坏。（P4199）"},
    {"id": "sp-769", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "验收前现场清理", "required_value": "建筑装饰装修工程验收前应将施工现场清理干净", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑装饰装修工程验收前应将施工现场清理干净。（P4200）"},
    {"id": "sp-770", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "门窗产品选型与确认", "required_value": "门窗产品应在符合设计要求的条件下选择国内知名和建筑市场推荐产品；产品品质、规格、外观和尺寸应符合设计要求；应提供产品样品给监理方和发包人确认，发包人同意后方可采购；进场材料应具有相应检测报告", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人拟用于本工程的门窗产品应在符合设计要求的条件下选择国内知名和建筑市场推荐产品。产品的品质、规格、外观和尺寸应符合设计要求。承包人应提供产品样品给监理方和发包人确认，发包人同意后方可采购。进场的材料应具有相应的检测报告。（P4202）"},
    {"id": "sp-771", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "门窗施工质量", "required_value": "门窗工程施工质量和检验标准应符合设计要求、DL/T5210.1-2021、GB50300和国家现行有关规范规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "门窗工程的施工质量和检验标准应符合设计要求、《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和国家现行有关规范的规定。（P4203）"},
    {"id": "sp-772", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修材料标准", "required_value": "建筑装饰装修工程所用材料品种、规格和质量应符合设计要求和国家现行标准规定；燃烧性能应符合设计要求和国家现行有关防火规范要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑装饰装修工程所用材料的品种、规格和质量应符合设计要求和国家现行标准的规定。建筑装饰装修材料的燃烧性能应符合设计要求和国家现行有关的防火规范要求。（P4206）"},
    {"id": "sp-773", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修材料选型与确认", "required_value": "建筑装饰装修材料应在符合设计要求的条件下选择国内知名和建筑市场推荐产品；品种、规格、外观和尺寸须经监理和发包人批准并提供样板确认后方可采购", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人拟用于本工程的建筑装饰装修材料应在符合设计要求的条件下选择国内知名和建筑市场推荐产品。产品的品种、规格、外观和尺寸须经过监理和发包人的批准，并提供样板给监理和发包人确认后方可采购。（P4207）"},
    {"id": "sp-774", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装修标准确认与专业施工", "required_value": "承包人提供办公楼及生活楼装修效果图经发包人签字确认后方可实施；装修主要材料、样式、颜色须经发包人批准方可采购；生产楼及生活楼装修必须由专业装修公司完成", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑装修标准：承包人提供办公楼及生活楼装修效果图，经发包人签字确认后方可实施。装修主要材料、样式、颜色须经发包人批准方可采购。生产楼及生活楼的装修必须由专业装修公司完成。（P4208）"},
    {"id": "sp-775", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "外墙保温防火", "required_value": "升压站外墙面图纸设计为保温墙面，保温层要求满足有关防火等级要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "升压站外墙面图纸设计为保温墙面，保温层要求满足有关防火等级要求。（P4209）"},
    {"id": "sp-776", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "一层地面防潮", "required_value": "一层地面要求均做防潮处理", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "一层地面要求均做防潮处理。（P4210）"},
    {"id": "sp-777", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "沟盖板、控制台与路缘石", "required_value": "沟盖板采用成品沟盖板，监控系统采用不锈钢控制台，升压站站内道路采用花岗岩路缘石", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "沟盖板采用成品沟盖板，监控系统采用不锈钢控制台，升压站站内道路采用花岗岩路缘石。（P4211）"},
    {"id": "sp-778", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "灯具开关品牌", "required_value": "灯具、开关采用国内名优品牌产品", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "灯具、开关：采用国内名优品牌产品。（P4212）"},
    {"id": "sp-779", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "未描述部位装修标准", "required_value": "未描述的部位装修标准以发包人要求为准，费用包含在总体报价中；设计方案（效果图）及采用的装修材料和产品规格、型号、颜色及标准等需经监理人审核、发包人确认或审批和备案", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "未描述的部位装修标准以发包人要求为准，费用包含在总体报价中；设计方案（效果图）及采用的装修材料和产品规格、型号、颜色及标准等需经监理人审核，发包人确认或审批和备案。（P4213）"},
    {"id": "sp-780", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修施工资质与方案", "required_value": "施工队伍应具备相应资质，人员应有相应岗位资格证书；承包人应编制施工组织设计并经监理和发包人审查批准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承担建筑装饰装修工程施工的队伍应具备相应的资质。承担建筑装饰装修工程施工的人员应有相应岗位的资格证书。承包人应编制施工组织设计并应经过监理和发包人的审查批准。（P4215）"},
    {"id": "sp-781", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修施工质量", "required_value": "施工质量应符合设计要求、DL/T5210.1-2021、GB50300和国家现行有关规范规定（如GB50210等）；违反设计文件和国家现行有关规范规定施工造成的质量问题应由承包人负责", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑装饰装修工程的施工质量应符合设计要求、《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和国家现行有关规范的规定（如《建筑装饰装修工程质量验收规范》GB50210等规范），由于违反设计文件和国家现行有关规范的规定施工造成的质量问题应由承包人负责。（P4216）"},
    {"id": "sp-782", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修环境保护", "required_value": "应遵守环境保护法律法规，采取有效措施控制施工现场粉尘、废气、废弃物、噪声、振动等对周围环境的污染和危害", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应遵守有关环境保护的法律法规，并应采取有效措施控制施工现场的各种粉尘、废气、废弃物、噪声、振动等对周围环境造成的污染和危害。（P4217）"},
    {"id": "sp-783", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "施工安全与劳保防火", "required_value": "应遵守施工安全、劳动保护、防火和防毒的法律法规，建立相应管理制度，配备必要的设备、器具和标识", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应遵守有关施工安全、劳动保护、防火和防毒的法律法规，应建立相应的管理制度，并应配备必要的设备、器具和标识。（P4218）"},
    {"id": "sp-784", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修半成品成品保护", "required_value": "施工过程中应做好半成品成品的保护，防止污染和损坏", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人在施工过程中应做好半成品成品的保护，防止污染和损坏。（P4219）"},
    {"id": "sp-785", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "装饰装修验收前清理", "required_value": "建筑装饰装修工程验收前应将施工现场清理干净", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑装饰装修工程验收前应将施工现场清理干净。（P4220）"},
    {"id": "sp-786", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "屋面材料质量证明", "required_value": "防水、保温隔热材料应有产品合格证书和性能检测报告，材料品种、规格、性能等应符合设计要求和现行国家产品标准；材料应经监理和发包人批准并提供样板确认后方可使用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程采用的防水、保温隔热材料应有产品合格证书和性能检测报告，材料的品种、规格，性能等应符合设计要求和现行国家产品标准。承包人拟用于本工程的材料应经过监理和发包人的批准，并提供样板给监理和发包人确认后方可使用。（P4222）"},
    {"id": "sp-787", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "屋面图纸会审与方案", "required_value": "屋面工程施工前应进行图纸会审，并编制屋面工程施工方案或技术措施，报监理和发包人审批", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程施工前，承包人应进行图纸会审，并编制屋面工程的施工方案或技术措施，报监理和发包人审批。（P4223）"},
    {"id": "sp-788", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "屋面三检制度", "required_value": "应建立各道工序的自检、交接检和专职人员检查的三检制度，并有完整检查记录；每道工序完成应经监理和发包人检查验收合格后方可进行下道工序施工", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程施工时，承包人应建立各道工序的自检、交接检和专职人员检查的“三检”制度，并有完整的检查记录、每道工序完成，应经过监理和发包人检查验收，合格后方可进行下道工序的施工。（P4224）"},
    {"id": "sp-789", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "防水层专业施工", "required_value": "防水层应由经资质审查合格的防水专业队伍施工，作业人员应持有建设行政主管部门颁发的上岗证", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程的防水层应由经资质审查合格的防水专业队伍进行施工。作业人员应持有建设行政主管部门颁发的上岗证。（P4225）"},
    {"id": "sp-790", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "保温防水层施工环境", "required_value": "保温层和防水层严禁在雨天和五级风及其以上时施工；施工环境气温宜符合GB50207规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面的保温层和防水层严禁在雨天和五级风及其以上时施工。施工环境气温宜符合《屋面工程质量验收规范》（GB50207）的规定。（P4226）"},
    {"id": "sp-791", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "屋面淋水蓄水试验", "required_value": "屋面工程完工后应进行淋水或蓄水试验", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程完工后应进行淋水或蓄水试验。（P4227）"},
    {"id": "sp-792", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "屋面施工质量", "required_value": "屋面工程施工应符合设计要求、DL/T5210.1-2021、GB50300和国家现行有关规范规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "屋面工程的施工应符合设计要求、应满足《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和国家现行有关规范的规定。（P4228）"},
    {"id": "sp-793", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "防腐蚀施工资质", "required_value": "施工队伍应具有相应资质等级和类似工程施工经验", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承担防腐工程的施工队伍应具有相应的资质等级和类似工程的施工经验。（P4230）"},
    {"id": "sp-794", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "防腐蚀原材料采购", "required_value": "原材料规格和性能参数应符合设计要求和国家现行有关规范规定，并经监理和发包人批准后方可采购", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人提供的原材料规格和性能参数应符合设计要求和国家现行有关规范的规定，并经过监理和发包人批准后方可采购。（P4231）"},
    {"id": "sp-795", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "防腐蚀材料质量证明", "required_value": "应提供产品合格证书、产品性能检测报告和进场复验报告", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应提供产品的合格证书、产品性能检测报告和进场复验报告。（P4232）"},
    {"id": "sp-796", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "防腐蚀施工质量", "required_value": "施工质量应符合设计要求、DL/T5210.1-2021、GB50300和国家现行有关规范规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "防腐蚀工程的施工质量应符合设计要求《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和国家现行有关规范的规定。（P4233）"},
    {"id": "sp-797", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "给排水施工资质与方案", "required_value": "施工队伍应具有相应资质，工程质量验收人员应具备相应专业技术资格；承包人应编制施工组织设计或施工方案，经监理和发包人审批后方可实施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑给水、排水的施工队伍应当具有相应的资质。工程质量验收人员应具备相应的专业技术资格。承包人应编制建筑给水、排水工程的施工组织设计或施工方案，经监理和发包人审批后方可实施。（P4235）"},
    {"id": "sp-798", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "给排水材料质量证明", "required_value": "主要材料、成品、半成品、配件、器具和设备必须具有中文质量合格证明文件，规格、型号及性能检测报告应符合国家技术标准或设计要求；进场材料品种、规格和性能等应经监理和发包人核查确认后方可使用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑给水、排水工程所使用的主要材料、成品、半成品、配件、器具和设备必须具有中文质量合格证明文件，规格、型号及性能检测报告应符合国家技术标准或设计要求。进场的材料的品种、规格和性能等应经过监理和发包人核查确认后方可使用。（P4236）"},
    {"id": "sp-799", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "给排水设备安装说明书", "required_value": "主要器具和设备必须有完整的安装使用说明书；承包人在运输、保管和施工过程中应采取有效措施防止损坏或腐蚀", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "主要器具和设备必须有完整的安装使用说明书。承包人在运输、保管和施工过程中，应采取有效措施防止损坏或腐蚀。（P4237）"},
    {"id": "sp-800", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "给排水施工质量", "required_value": "施工应符合设计要求、DL/T5210.1-2021、GB50300和GB50242规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "建筑给水、排水施工应符合设计要求、应满足《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和《建筑给水排水及采暖工程施工质量验收规范》（GB50242）的规定。（P4238）"},
    {"id": "sp-801", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "电气产品3C认证", "required_value": "电气产品应是取得3C认证的产品；主要电气设备、材料、成品和半成品品种、规格和性能应符合设计要求，进场前应经监理和发包人批准方可进场使用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人用于本工程的电气产品应是取得3C认证的产品。主要电气设备、材料、成品和半成品的品种、规格和性能应符合设计要求。主要电气设备、材料、成品和半成品进场前应经过监理和发包人的批准，方可进场使用。（P4240）"},
    {"id": "sp-802", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "电气工程作业与质量", "required_value": "作业人员应持有岗位证书；施工质量、电气设备调试和通电试运行应符合设计要求、DL/T5210.1-2021、GB50300和GB50303规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "电气工程的作业人员应持有有关的岗位证书。电气工程的施工质量、电气设备的调试和通电试运行应符合设计要求、应满足《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和《建筑电气工程施工质量验收规范》（GB50303）的规定。（P4241）"},
    {"id": "sp-803", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调施工资质", "required_value": "施工队伍应具有相应工程施工承包的资质等级，作业人员应有相应岗位资格证书", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承担通风与空调工程的施工队伍应具有相应工程施工承包的资质等级，作业人员应有相应岗位的资格证书。（P4243）"},
    {"id": "sp-804", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调材料进场批准", "required_value": "主要原材料、成品、半成品和设备在进场前必须经监理和发包人批准后方可进场使用", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "通风和空调工程所采用的主要原材料、成品、半成品和设备在进场前，必须经过监理和发包人的批准后方可进场使用。（P4244）"},
    {"id": "sp-805", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调施工程序与会检", "required_value": "施工应按规定的程序进行，并与建筑及其他专业工种互相配合，服从发包人统一安排；与通风与空调系统有关的建筑工程施工完毕后应由发包人、监理、设计及承包人共同会检", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "通风与空调工程的施工应按规定的程序进行，并与建筑及其他专业工种互相配合，并服从发包人的统一安排。与通风与空调系统有关的建筑工程施工完毕后，应由发包人、监理、设计及承包人共同会检。（P4245）"},
    {"id": "sp-806", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调系统调试", "required_value": "竣工的系统调试应在监理和发包人共同参与下进行，承包人应具有专业检测人员和符合有关标准规定的测试仪器", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "通风与空调工程竣工的系统调试，应在监理和发包人共同参与下进行，承包人应具有专业检测人员和符合有关标准规定的测试仪器。（P4246）"},
    {"id": "sp-807", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调保修期", "required_value": "保修期限自竣工验收合格日起计算为两个采暖期、供冷期；保修期内发生施工质量问题的承包人应履行保修职责", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "通风与空调工程施工质量的保修期限，自竣工验收合格日起计算为两个采暖期、供冷期。在保修期内发生施工质量问题的，承包人应履行保修职责。（P4247）"},
    {"id": "sp-808", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "通风空调施工质量", "required_value": "施工质量应符合设计要求、DL/T5210.1-2021、GB50300和GB50243规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "通风与空调工程的施工质量应符合设计要求、应满足《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和《通风与空调工程施工质量验收规范》（GB50243）的规定。（P4248）"},
    {"id": "sp-809", "clause": "第五章4.4.8升压站土建", "page": "n/a-无分页",
     "requirement": "标志标识装涂", "required_value": "承包人应根据发包人要求在需要的建筑物及设备上装涂投资方标志、标识，施工之前需将设计方案报送发包人审批通过", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应根据发包人的要求，在需要的建筑物及设备上裝涂投资方标志、标识，承包人在施工之前需将设计方案报送发包人审批通过。（P4250）"},
    {"id": "sp-810", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "钢结构原材料及成品采购", "required_value": "发包人负责采购原材料及成品，应符合设计要求和现行国家产品标准，品种、规格、性能应经监理和发包人批准方可采购", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "发包人负责采购原材料及成品，应符合设计要求和现行国家产品标准，并且原材料和成品的品种、规格、性能应经过监理和发包人批准，方可采购。（P4253）"},
    {"id": "sp-811", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "钢材全数检查", "required_value": "进场的钢材、高强螺栓等原材料及成品须全数检查，质量合格证明书文件、中文标志及检验报告等应符合设计要求和现行国家产品标准", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "进场的钢材、高强螺栓等原材料及成品须全数检查，质量合格证明书文件、中文标志及检验报告等应符合设计要求和现行国家产品标准。（P4254）"},
    {"id": "sp-812", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "高强度螺栓抗滑移系数试验", "required_value": "按设计要求、DL/T5210.1-2021、GB50300和GB50205规定进行高强度螺栓连接摩擦面的抗滑移系数试验和复验，现场处理的构件摩擦面应单独进行试验，结果应符合设计要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人应按设计要求、《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和《钢结构工程施工质量验收规范》（GB50205）的规定分别进行高强度螺栓连接摩擦面的抗滑移系数试验和复验，现场处理的构件摩擦面应单独进行摩擦面抗滑移系数试验，其结果应符合设计要求。（P4256）"},
    {"id": "sp-813", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "高强螺栓施拧要求", "required_value": "高强螺栓连接副的施拧顺序和初拧、复拧扭距应符合设计要求和国家现行行业标准JGJ82规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "高强螺栓连接副的施拧顺序和初拧、复拧扭距应符合设计要求和国家现行行业标准《钢结构高强度螺栓连接的设计施工及验收规程》JGJ82的规定。（P4257）"},
    {"id": "sp-814", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "钢结构安装前验收", "required_value": "钢结构安装前应验收建筑物的定位轴线、基础轴线和标高、地脚螺栓的规格及紧固是否符合设计要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "钢结构安装前，应验收建筑物的定位轴线、基础轴线和标高、地脚螺栓的规格及紧固是否符合设计要求。（P4258）"},
    {"id": "sp-815", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "钢构件变形矫正", "required_value": "钢构件的运输、堆放和吊装等造成的钢构件变形及涂层脱落，应进行矫正和修补", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "钢构件的运输、堆放和吊装等造成的钢构件变形及涂层脱落，应进行矫正和修补。（P4259）"},
    {"id": "sp-816", "clause": "第五章4.4.9钢结构", "page": "n/a-无分页",
     "requirement": "钢结构安装允许偏差", "required_value": "钢柱安装允许偏差、钢梁/次梁及受压构件垂直度和侧向弯曲矢高允许偏差、压型钢板安装允许偏差等应符合设计要求、DL/T5210.1-2021、GB50300和GB50205规定", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "钢柱的安装允许偏差，钢梁、次梁及受压构件的垂直度和侧向弯曲矢高的允许偏差，压型钢板安装的允许偏差等应符合设计要求、《电力建设施工质量验收及评定规程》（第1部分：土建工程DL/T5210.1-2021）、《建筑工程施工质量验收统一标准》（GB50300）和《钢结构工程施工质量验收规范》（GB50205）的规定。（P4260）"},
    {"id": "sp-817", "clause": "第五章4.4.10检测验收", "page": "n/a-无分页",
     "requirement": "土建工程施工质量", "required_value": "土建工程的施工质量应符合国家相关的工程建设施工质量验收规范及标准要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "土建工程的施工质量应符合国家相关的工程建设施工质量验收规范及标准要求等。（P4262）"},
    {"id": "sp-818", "clause": "第五章4.4.10检测验收", "page": "n/a-无分页",
     "requirement": "第三方检测要求", "required_value": "承包人须满足经发包人认可的第三方检测机构对已完成工程的检测要求", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包人须满足经发包人认可的第三方检测机构对已完成工程的检测要求。（P4263）"},
