    {"id": "sp-1210", "clause": "第五章9.1工程质量管理", "page": "n/a-无分页",
     "requirement": "承包人必须提交的安全文明施工管理制度（34 项清单组）", "required_value": "提交包括安全生产委员会工作、安全生产费用、安全工作例会、安全生产承诺、安全检查、安全文明施工管理、安全教育培训、受限空间管理、安全施工措施交底、安全施工作业票、安全环保设施、劳保用品、隐患排查、高空作业、工程变更、安全文明施工奖惩、安全过程管理、各级人员安全责任制、现场安全一票否决、大型机械/中小型机工具管理、消防、防火防爆、治安保卫、交通、特种作业人员、职业卫生、危险化学品、应急准备与响应、重大风险作业与重大危险源、危险因素识别评价控制、事故信息管理、事故报告调查处理统计等共 34 项制度", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "《安全生产委员会工作制度》……《事故报告、调查、处理、统计制度》（P5259；P5292）"},
    {"id": "sp-1211", "clause": "第五章9.2HSE（健康、安全与环境管理体系）", "page": "n/a-无分页",
     "requirement": "承包商需具备完整 HSE 体系", "required_value": "承包商需具备完整的 HSE（健康、安全与环境管理）体系", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "承包商需具备完整的HSE体系。（P5294）"},
    {"id": "sp-1212", "clause": "第五章9.2HSE（健康、安全与环境管理体系）", "page": "n/a-无分页",
     "requirement": "HSE 方案由投标方提出并征求招标方同意", "required_value": "HSE 方案由投标方提出并征求招标方同意；贯彻“安全第一，预防为主”方针和“安全为天”管理思想，提高安健环管理水平，保障职工安全与健康，努力创建安全文明施工样板工程", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "由投标方提出并征求招标方的同意。投标方应贯彻“安全第一，预防为主”的方针和 “安全为天”的管理思想，提高工程建设过程安健环管理水平，保障职工在劳动过程中的安全与健康。根据地方承包工程的有关安全环保管理规定、原国家电力公司有关安全环保文件和国家有关法律法规的规定，努力创建安全文明施工样板工程。（P5295）"},
    {"id": "sp-1213", "clause": "第五章9.2HSE（健康、安全与环境管理体系）", "page": "n/a-无分页",
     "requirement": "HSE 需具备 a 可操作性程序文件清单", "required_value": "需具备可操作性程序文件清单", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "a可操作性程序文件清单（P5297）"},
    {"id": "sp-1214", "clause": "第五章9.2HSE（健康、安全与环境管理体系）", "page": "n/a-无分页",
     "requirement": "HSE 需具备 b 重大危险因素与环境因素清单", "required_value": "需具备项目职业安全、健康重大危险因素清单和重大环境因素清单", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "b项目职业安全、健康重大危险因素清单和重大环境因素清单（P5298）"},
    {"id": "sp-1215", "clause": "第五章9.2HSE（健康、安全与环境管理体系）", "page": "n/a-无分页",
     "requirement": "HSE 需具备 c 健康安全与环境管理措施", "required_value": "需具备项目健康安全管理措施和环境管理措施", "unit": "",
     "tolerance": "", "no_negative_allowed": True,
     "raw_text": "c项目健康安全管理措施和环境管理措施（P5299）"},
