SOURCE = {"file": "示例发包人示例市100MW风电项目EPC总承包工程招标文件.docx",
          "page_range": "n/a-无分页（docx 无稳定页码，raw_text 尾部（Pxxxx）为段号锚点）。第五章「发包人要求」P3229–P5390 分阶段全量：已全量 9 节——1.总则 P3229–P3332（101 行，sp-238–338）／2.性能指标 P3333–P3353（14 行，sp-003–016）／3.勘察设计要求 P3354–P3603（69 行，sp-017–085，含 3.5 规范清单组 P3436 及 P3437–P3602 共 166 项）／4.施工安装要求 P3604–P4477（571 行，sp-339–909，含表 T33/T34/T35/T36/T37 逐行；4.3.6 储能（不涉及）不抽；4.9 P4405–P4476 规范清单组〔72 项〕＋P4477 兜底条款）／5.风电场调试、试运行和验收 P4478–P4483（5 行，sp-086–090）／6.施工工期要求 P4484–P4504（16 行，sp-091–106，T38 填写模板不拆行）／7.施工质量要求 P4505–P4891（279 行，sp-910–1188：7.1 43＋7.2 95＋7.3 98＋7.4 43）／8.竣工试验与验收 P4892–P5138＋表 T39（131 行，sp-107–237，含 T39R3–R7 逐行）／9.工程管理 P5139–P5389（78 行，sp-1189–1266：9.1 22＋9.2 6＋9.3 12＋9.4 10＋9.5 16＋9.6 12，含 5 组标准清单与 3 组管理制度清单组行；T40–T42 承包人填写空白表不拆行）；第五章 1–9 节全量覆盖"}


def build_01b():
    """序列化 01b_spec-items.json（契约 0.1，assets/spec-items.schema.json）。"""
    return {
        "schema_version": "0.1",
        "source": SOURCE,
        "items": SPEC_ITEMS,
    }


def main():
    ap = argparse.ArgumentParser(description="生成 01b_spec-items.json（技术规范条目抄行）")
    ap.add_argument("--bid", help="项目 bid 目录（与 --out 二选一）")
    ap.add_argument("--out", help="输出文件路径（与 --bid 二选一）")
    args = ap.parse_args()
    if not args.bid and not args.out:
        ap.error("必须指定 --bid 或 --out")
    p = os.path.join(args.bid, "01b_spec-items.json") if args.bid else args.out
    with open(p, "w", encoding="utf-8") as f:
        json.dump(build_01b(), f, ensure_ascii=False, indent=2)
    print("OK", p)
    print("⚠️ 第五章已全量 9 节（1–9 全覆盖）：1.总则 101 行（sp-238–338）＋2.性能指标 14 行（sp-003–016）"
          "＋3.勘察设计 69 行（sp-017–085）＋4.施工安装要求 571 行（sp-339–909，4.1–4.9）"
          "＋5.风电场调试、试运行和验收 5 行（sp-086–090）＋6.施工工期 16 行（sp-091–106）"
          "＋7.施工质量要求 279 行（sp-910–1188，7.1–7.4）＋8.竣工试验与验收 131 行（sp-107–237）"
          "＋9.工程管理 78 行（sp-1189–1266，9.1–9.6）"
          "（共 %d 行，含合同条款/前附表来源 2 行）" % len(SPEC_ITEMS))


if __name__ == "__main__":
    main()
